
import * as THREE from "three";

/* ============================================================
   JUJUTSU BATTLEGROUND — Jujutsu Shenanigans style 3D arena
   Characters:
     GOJO  — Limitless (Red / Rapid / Twofold / Palm / Teleport)
     NAOYA — Projection Sorcery, 24 FPS rule, frames, bleed
   ============================================================ */

let ARENA = 88;
let timeScale = 1, hitstopT = 0;

/* ---------------- renderer / scene ---------------- */
let potatoAtBoot = false;
try { potatoAtBoot = localStorage.getItem('jj.potatoMode') === '1'; } catch (_) {}
const renderer = new THREE.WebGLRenderer({ antialias: !potatoAtBoot });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, potatoAtBoot ? .75 : 1.5));
renderer.shadowMap.enabled = !potatoAtBoot;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87b8e8);
scene.fog = new THREE.Fog(0x87b8e8, 90, 260);

const camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, 0.1, 900);

const hemi = new THREE.HemisphereLight(0xcfe4ff, 0x4a4438, 0.9);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff2d8, 1.6);
sun.position.set(60, 90, 40);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -110; sun.shadow.camera.right = 110;
sun.shadow.camera.top = 110; sun.shadow.camera.bottom = -110;
sun.shadow.camera.far = 300;
scene.add(sun);

const shatterCv = document.getElementById("shatterCv");
const shCtx = shatterCv.getContext("2d");
function sizeShatter() { shatterCv.width = innerWidth; shatterCv.height = innerHeight; }
sizeShatter();

addEventListener("resize", () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  sizeShatter();
});

/* ---------------- textures ---------------- */
function canvasTex(w, h, fn, repX = 1, repY = 1) {
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  fn(c.getContext("2d"));
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repX, repY);
  t.magFilter = THREE.NearestFilter;
  return t;
}
const groundTex = canvasTex(256, 256, g => {
  g.fillStyle = "#5a5f66"; g.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 900; i++) {
    g.fillStyle = Math.random() < .5 ? "#54595f" : "#61666d";
    g.fillRect(Math.random() * 256, Math.random() * 256, 3, 3);
  }
  g.strokeStyle = "#484c52"; g.lineWidth = 3;
  g.strokeRect(0, 0, 256, 256);
  g.fillStyle = "#d8d2c0";
  g.fillRect(120, 0, 16, 60); g.fillRect(120, 100, 16, 60); g.fillRect(120, 200, 16, 56);
}, 22, 22);

function buildingTex(base, win) {
  return canvasTex(128, 256, g => {
    g.fillStyle = base; g.fillRect(0, 0, 128, 256);
    for (let y = 12; y < 244; y += 24) {
      for (let x = 10; x < 118; x += 22) {
        g.fillStyle = Math.random() < .35 ? win : "#20242e";
        g.fillRect(x, y, 13, 15);
        g.fillStyle = "rgba(255,255,255,.12)";
        g.fillRect(x, y, 13, 3);
      }
    }
  });
}

/* ---------------- arena ---------------- */
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(ARENA * 2 + 60, ARENA * 2 + 60),
  new THREE.MeshStandardMaterial({ map: groundTex, roughness: .95 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

const buildingAABBs = [];
const buildingMats = [
  new THREE.MeshStandardMaterial({ map: buildingTex("#8d97a5", "#ffe9a0"), roughness: .8 }),
  new THREE.MeshStandardMaterial({ map: buildingTex("#a89a8c", "#c8ecff"), roughness: .8 }),
  new THREE.MeshStandardMaterial({ map: buildingTex("#7f8a99", "#ffd27a"), roughness: .8 }),
];
function addBuilding(x, z, w, d, h, mat) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat || buildingMats[Math.floor(Math.random() * 3)]);
  m.position.set(x, h / 2, z);
  m.castShadow = m.receiveShadow = true;
  scene.add(m);
  const pad = .6;
  buildingAABBs.push({
    minX: x - w / 2 - pad, maxX: x + w / 2 + pad,
    minZ: z - d / 2 - pad, maxZ: z + d / 2 + pad,
    h, mesh: m, extras: []
  });
  return m;
}

/* crates — maps.js puts them on sidewalks, never inside a wall */
const crateMat = new THREE.MeshStandardMaterial({ color: 0xb98a4a, roughness: .9 });
const crateGeo = new THREE.BoxGeometry(1.6, 1.6, 1.6);
const crates = [];
function addCrate(x, z) {
  const m = new THREE.Mesh(crateGeo, crateMat);
  m.position.set(x, 0.8, z);
  m.castShadow = m.receiveShadow = true;
  scene.add(m);
  crates.push({ mesh: m, vel: new THREE.Vector3(), av: new THREE.Vector3() });
  return m;
}

/* ============================================================
   R15 THIN ANIME RIG — supports Gojo / Naoya / enemy variants
   ============================================================ */
function boxMesh(w, h, d, color) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d),
    new THREE.MeshStandardMaterial({ color, roughness: .72 }));
  m.castShadow = true;
  return m;
}

function makeAnimeRig(cfg) {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);
  const M = boxMesh;
  const HIPS_Y = 2.56;

  /* pelvis */
  const hips = new THREE.Group(); hips.position.y = HIPS_Y; body.add(hips);
  const pelvis = M(1.0, .72, .58, cfg.pants); pelvis.position.y = .36; hips.add(pelvis);
  if (cfg.naoya) {
    /* hakama skirt + himo belt with knot */
    const skirt = M(1.18, .52, .74, cfg.pants); skirt.position.y = .2; hips.add(skirt);
    const belt = M(1.1, .16, .68, 0x3c414e); belt.position.y = .68; hips.add(belt);
    const knot = M(.3, .18, .14, 0x4a505e); knot.position.set(0, .66, .4); hips.add(knot);
    const strapL = M(.12, .5, .1, 0xdadee6); strapL.position.set(-.12, .38, .4); strapL.rotation.z = .12; hips.add(strapL);
    const strapR = strapL.clone(); strapR.position.x = .12; strapR.rotation.z = -.12; hips.add(strapR);
  } else {
    const belt = M(1.04, .12, .62, 0x0b0c12); belt.position.y = .72; hips.add(belt);
  }

  /* chest */
  const spine = new THREE.Group(); spine.position.y = .76; hips.add(spine);
  const chest = M(1.28, 1.1, .64, cfg.torso); chest.position.y = .55; spine.add(chest);
  if (cfg.naoya) {
    /* kimono lapels crossing + white under-collar */
    const lapL = M(.6, 1.0, .1, 0x232946); lapL.position.set(-.24, .58, .3); lapL.rotation.z = .32; spine.add(lapL);
    const lapR = M(.6, 1.0, .1, 0x1b2038); lapR.position.set(.24, .58, .32); lapR.rotation.z = -.32; spine.add(lapR);
    const underc = M(.4, .42, .12, 0xf2f2ee); underc.position.set(0, .96, .3); spine.add(underc);
    const btn1 = M(.05, .05, .04, 0xb8bcc4); btn1.position.set(0, 1.0, .38); spine.add(btn1);
    const btn2 = btn1.clone(); btn2.position.y = .88; spine.add(btn2);
  }

  /* neck + head */
  const neck = new THREE.Group(); neck.position.y = 1.12; spine.add(neck);
  const neckM = M(.26, .24, .26, cfg.naoya ? 0xf2f2ee : cfg.skin); neckM.position.y = .08; neck.add(neckM);
  const head = new THREE.Group(); head.position.y = .18; neck.add(head);
  const skull = M(.9, .92, .9, cfg.skin); skull.position.y = .48; head.add(skull);

  if (cfg.gojo) {
    const hairStart = head.children.length;
    const hairC = 0xf2f6ff;
    const hairTop = M(1.0, .36, .98, hairC); hairTop.position.y = .96; head.add(hairTop);
    const hairBack = M(.98, .5, .24, hairC); hairBack.position.set(0, .78, -.38); head.add(hairBack);
    for (let i = 0; i < 8; i++) {
      const th = i / 8 * Math.PI * 2;
      const s = M(.2, .42 + Math.random() * .28, .2, hairC);
      s.position.set(Math.cos(th) * .27, 1.2, Math.sin(th) * .27);
      s.rotation.z = -Math.cos(th) * .5;
      s.rotation.x = Math.sin(th) * .5;
      head.add(s);
    }
    const sTop = M(.22, .5, .22, hairC); sTop.position.y = 1.3; sTop.rotation.z = .12; head.add(sTop);
    for (let i = -1; i <= 1; i++) {
      const b = M(.26, .34, .1, hairC);
      b.position.set(i * .27, .86, .44);
      b.rotation.x = -.12;
      head.add(b);
    }
    head.children.slice(hairStart).forEach(m => { m.userData.gojoHair = true; });
    const bf = M(.96, .26, .96, 0x0d0e14); bf.position.y = .58; head.add(bf);
    const collar = M(1.04, .42, .72, 0x11142a); collar.position.set(0, 1.08, 0); spine.add(collar);
  } else if (cfg.naoya) {
    const hairC = 0x8f9c52, hairD = 0x76833f;
    /* swept olive hair */
    const hairTop = M(1.0, .34, 1.0, hairC); hairTop.position.set(0, .96, -.04); head.add(hairTop);
    const hairBack = M(.96, .62, .26, hairD); hairBack.position.set(0, .68, -.4); head.add(hairBack);
    /* swept-back spikes */
    for (let i = 0; i < 5; i++) {
      const s = M(.2, .4 + Math.random() * .2, .22, i % 2 ? hairC : hairD);
      s.position.set(-.34 + i * .17, 1.16, -.1 - (i % 2) * .12);
      s.rotation.x = .55;
      s.rotation.z = (i - 2) * .1;
      head.add(s);
    }
    /* asymmetric fringe (longer over right eye) */
    const b1 = M(.3, .32, .1, hairC); b1.position.set(-.26, .88, .43); b1.rotation.x = -.1; head.add(b1);
    const b2 = M(.26, .46, .1, hairD); b2.position.set(.03, .82, .45); b2.rotation.x = -.12; b2.rotation.z = -.08; head.add(b2);
    const b3 = M(.28, .58, .1, hairC); b3.position.set(.3, .76, .44); b3.rotation.x = -.14; b3.rotation.z = -.14; head.add(b3);
    /* narrow smug eyes + brows + smirk */
    const e1 = M(.15, .07, .05, 0x2a2418); e1.position.set(-.2, .56, .46); head.add(e1);
    const e2 = M(.15, .07, .05, 0x2a2418); e2.position.set(.2, .56, .46); head.add(e2);
    const br1 = M(.17, .05, .05, hairD); br1.position.set(-.2, .66, .46); br1.rotation.z = -.18; head.add(br1);
    const br2 = M(.17, .05, .05, hairD); br2.position.set(.2, .66, .46); br2.rotation.z = .18; head.add(br2);
    const smirk = M(.2, .04, .04, 0xb87a5e); smirk.position.set(.08, .26, .46); smirk.rotation.z = .16; head.add(smirk);
    /* tall white shirt collar */
    const collar = M(.62, .34, .56, 0xf2f2ee); collar.position.set(0, 1.16, .02); spine.add(collar);
  } else if (cfg.face) {
    const e1 = M(.13, .13, .05, 0x14141c), e2 = e1.clone();
    e1.position.set(-.2, .58, .45); e2.position.set(.2, .58, .45);
    head.add(e1, e2);
  }

  /* arms */
  const armW = cfg.naoya ? .52 : .36;
  function arm(side) {
    const sh = new THREE.Group(); sh.position.set(.76 * side + (cfg.naoya ? .04 * side : 0), .92, 0); spine.add(sh);
    const pad = M(cfg.naoya ? .58 : .46, .4, cfg.naoya ? .58 : .46, cfg.torso); pad.position.y = -.1; sh.add(pad);
    const up = M(armW, 1.0, armW, cfg.torso); up.position.y = -.52; sh.add(up);
    const el = new THREE.Group(); el.position.y = -1.02; sh.add(el);
    if (cfg.naoya) {
      /* wide kimono sleeve to mid-forearm, then white shirt cuff */
      const sleeve = M(.5, .5, .5, cfg.torso); sleeve.position.y = -.22; el.add(sleeve);
      const cuff = M(.34, .5, .34, 0xf2f2ee); cuff.position.y = -.68; el.add(cuff);
    } else {
      const lo = M(.32, .92, .32, cfg.torso); lo.position.y = -.46; el.add(lo);
    }
    const hand = M(.32, .28, .34, cfg.skin); hand.position.y = -1.04; el.add(hand);
    const anchor = new THREE.Object3D(); anchor.position.y = -1.2; el.add(anchor);
    return { sh, el, anchor };
  }
  const aL = arm(-1), aR = arm(1);

  /* legs (naoya: wide hakama trousers) */
  const upW = cfg.naoya ? .62 : .46, loW = cfg.naoya ? .56 : .4;
  function leg(side) {
    const hip = new THREE.Group(); hip.position.set(.3 * side, .04, 0); hips.add(hip);
    const up = M(upW, 1.18, cfg.naoya ? .64 : .48, cfg.pants); up.position.y = -.59; hip.add(up);
    const kn = new THREE.Group(); kn.position.y = -1.18; hip.add(kn);
    const lo = M(loW, 1.14, cfg.naoya ? .58 : .42, cfg.pants2 || cfg.pants); lo.position.y = -.57; kn.add(lo);
    const an = new THREE.Group(); an.position.y = -1.14; kn.add(an);
    const foot = M(.42, .24, .78, cfg.shoes); foot.position.set(0, -.12, .14); an.add(foot);
    return { hip, kn, an };
  }
  const lL = leg(-1), lR = leg(1);

  const rig = {
    root, body, hips, spine, neck, head,
    shoulderL: aL.sh, elbowL: aL.el, handL: aL.anchor,
    shoulderR: aR.sh, elbowR: aR.el, handR: aR.anchor,
    hipL: lL.hip, kneeL: lL.kn, ankleL: lL.an,
    hipR: lR.hip, kneeR: lR.kn, ankleR: lR.an,
    hipsBaseY: HIPS_Y,
  };

  if (cfg.naoya) {
    /* tanto blade, hidden until used */
    const tanto = new THREE.Group();
    const blade = boxMesh(.07, .6, .13, 0xe8edf4); blade.position.y = -.42; tanto.add(blade);
    const guard = boxMesh(.16, .05, .2, 0x3a3f4c); guard.position.y = -.1; tanto.add(guard);
    const grip = boxMesh(.09, .22, .11, 0x23262e); grip.position.y = .04; tanto.add(grip);
    tanto.position.y = -1.15;
    tanto.visible = false;
    aR.el.add(tanto);
    rig.tanto = tanto;
  }
  return rig;
}
const JOINTS = ["hips","spine","neck","head","shoulderL","shoulderR","elbowL","elbowR","hipL","hipR","kneeL","kneeR","ankleL","ankleR"];
function resetPose(r) {
  for (const j of JOINTS) r[j].rotation.set(0, 0, 0);
  r.hips.position.y = r.hipsBaseY;
  r.hips.position.x = 0;
}

const GOJO_CFG  = { gojo: true, torso: 0x191d33, pants: 0x14151d, shoes: 0x1c1e2e, skin: 0xf2c992 };
const NAOYA_CFG = { naoya: true, torso: 0x1b2038, pants: 0xc9cdd4, pants2: 0xbfc3cb, shoes: 0x2a2c34, skin: 0xf2c992 };
const DUMMY_CFG  = { face: true, torso: 0xc9a06a, pants: 0x8a6b44, shoes: 0x5c4630, skin: 0xd8b57e };
const ATTACK_CFG = { face: true, torso: 0xa8433a, pants: 0x5c2a26, shoes: 0x33201e, skin: 0xe6c26a };

/* ============================================================
   ANIMATION — procedural idle / walk / run / air (+ per-char flair)
   ============================================================ */
const lerp = (a, b, w) => a + (b - a) * w;
const clamp01 = x => Math.max(0, Math.min(1, x));
const ease = x => x * x * (3 - 2 * x);

function applyLocomotion(r, t, gait, moveAmt, runAmt, onGround, vy) {
  if (window.JJMOVE) return JJMOVE.locomotion(r, t, gait, moveAmt, runAmt, onGround, vy);
  if (!onGround) {
    r.spine.rotation.x = vy > 2 ? .1 : -.14;
    r.shoulderL.rotation.x = -.55; r.shoulderR.rotation.x = -.55;
    r.shoulderL.rotation.z = -.5;  r.shoulderR.rotation.z = .5;
    r.elbowL.rotation.x = -.5;     r.elbowR.rotation.x = -.5;
    r.hipL.rotation.x = -.55; r.kneeL.rotation.x = .85;
    r.hipR.rotation.x = .25;  r.kneeR.rotation.x = .5;
    r.ankleL.rotation.x = .2; r.ankleR.rotation.x = .25;
    return;
  }
  const w = ease(moveAmt);
  const run = ease(runAmt);
  const sL = Math.sin(gait), cL = Math.cos(gait);
  const sR = Math.sin(gait + Math.PI), cR = Math.cos(gait + Math.PI);

  const br = Math.sin(t * 2.1) * .5 + .5;
  const idle = {
    spineX: .03 + br * .022, spineY: Math.sin(t * .4) * .04,
    neckX: -.05 + br * .018, neckY: Math.sin(t * .33) * .16,
    shX: .06 + br * .04, elX: -.18 - br * .05,
    hipsY: -.02 * br, hipsRotY: Math.sin(t * .5) * .03,
    hipX: 0, kneeX: .06,
  };
  const legAmp = lerp(.5, 1.02, run);
  const armAmp = lerp(.42, .95, run);
  const kneeAmp = lerp(.55, 1.25, run);
  const lean = lerp(-.05, -.24, run);
  const bobAmp = lerp(.05, .11, run);

  r.hipL.rotation.x = lerp(idle.hipX, -sL * legAmp, w);
  r.hipR.rotation.x = lerp(idle.hipX, -sR * legAmp, w);
  r.kneeL.rotation.x = lerp(idle.kneeX, .08 + Math.max(0, cL) * kneeAmp + run * .18, w);
  r.kneeR.rotation.x = lerp(idle.kneeX, .08 + Math.max(0, cR) * kneeAmp + run * .18, w);
  r.ankleL.rotation.x = lerp(0, -(r.hipL.rotation.x + r.kneeL.rotation.x) * .38, w);
  r.ankleR.rotation.x = lerp(0, -(r.hipR.rotation.x + r.kneeR.rotation.x) * .38, w);
  r.hipL.rotation.z = lerp(-.035, 0, w);
  r.hipR.rotation.z = lerp(.035, 0, w);

  r.shoulderL.rotation.x = lerp(idle.shX, sL * armAmp, w);
  r.shoulderR.rotation.x = lerp(idle.shX, sR * armAmp, w);
  r.shoulderL.rotation.z = lerp(-.08, -.06, w);
  r.shoulderR.rotation.z = lerp(.08, .06, w);
  r.elbowL.rotation.x = lerp(idle.elX, -.2 - Math.max(0, -sL) * (.3 + run * .8) - run * .45, w);
  r.elbowR.rotation.x = lerp(idle.elX, -.2 - Math.max(0, -sR) * (.3 + run * .8) - run * .45, w);

  r.spine.rotation.x = lerp(idle.spineX, lean, w);
  r.spine.rotation.y = lerp(idle.spineY, sL * .09, w);
  r.neck.rotation.x = lerp(idle.neckX, -lean * .55, w);
  r.neck.rotation.y = lerp(idle.neckY, -sL * .05, w);
  r.hips.rotation.y = lerp(idle.hipsRotY, -sL * .1, w);

  r.hips.position.y = r.hipsBaseY + lerp(idle.hipsY, -(1 - Math.abs(cL)) * bobAmp, w);
}

/* Naoya's arrogant idle / swagger / anime sprint, layered on top */
function applyNaoyaFlair(r, t, moveAmt, runAmt, onGround) {
  if (!onGround) return;
  const idleW = 1 - ease(moveAmt);
  if (idleW > .05) {
    /* right hand on hip, chin up, weight on one leg */
    r.shoulderR.rotation.x = lerp(r.shoulderR.rotation.x, .3, idleW);
    r.shoulderR.rotation.z = lerp(r.shoulderR.rotation.z, .62, idleW);
    r.elbowR.rotation.x = lerp(r.elbowR.rotation.x, -1.18, idleW);
    r.neck.rotation.x = lerp(r.neck.rotation.x, -.14, idleW);
    r.neck.rotation.z = lerp(r.neck.rotation.z, .07, idleW);
    r.spine.rotation.z = lerp(0, -.045, idleW);
    r.hips.position.x = lerp(r.hips.position.x, .1, idleW);
    r.hipL.rotation.z = lerp(r.hipL.rotation.z, -.1, idleW);
    /* occasional hair caress with the left hand */
    const cyc = t % 8;
    if (cyc < 1.6) {
      const k = Math.sin(Math.PI * clamp01(cyc / 1.6)) * idleW;
      r.shoulderL.rotation.x = lerp(r.shoulderL.rotation.x, -2.5, k);
      r.elbowL.rotation.x = lerp(r.elbowL.rotation.x, -1.5, k);
      r.neck.rotation.z = lerp(r.neck.rotation.z, -.1, k);
    }
  }
  const runW = ease(runAmt) * ease(moveAmt);
  if (runW > .05) {
    /* anime sprint: deep lean, arms swept back, chin forward */
    r.spine.rotation.x = lerp(r.spine.rotation.x, -.42, runW);
    r.neck.rotation.x = lerp(r.neck.rotation.x, .3, runW);
    r.shoulderL.rotation.x = lerp(r.shoulderL.rotation.x, .78, runW);
    r.shoulderR.rotation.x = lerp(r.shoulderR.rotation.x, .85, runW);
    r.shoulderL.rotation.z = lerp(r.shoulderL.rotation.z, -.3, runW);
    r.shoulderR.rotation.z = lerp(r.shoulderR.rotation.z, .3, runW);
    r.elbowL.rotation.x = lerp(r.elbowL.rotation.x, -.2, runW);
    r.elbowR.rotation.x = lerp(r.elbowR.rotation.x, -.2, runW);
  }
}

/* ---------------- vfx helpers ---------------- */
function radialSprite(inner, outer) {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  const gr = g.createRadialGradient(32, 32, 2, 32, 32, 32);
  gr.addColorStop(0, inner); gr.addColorStop(1, outer);
  g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}
const TEX_GLOW = radialSprite("rgba(255,255,255,1)", "rgba(255,255,255,0)");

const fx = [];
function addFx(obj) { fx.push(obj); }

function spark(pos, color, n = 6, spd = 14, size = 1.4) {
  for (let i = 0; i < n; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({
      map: TEX_GLOW, color, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    s.position.copy(pos);
    const v = new THREE.Vector3((Math.random() - .5), (Math.random() - .3), (Math.random() - .5)).normalize().multiplyScalar(spd * (0.4 + Math.random() * .8));
    const life = .3 + Math.random() * .25;
    s.scale.setScalar(size * (0.6 + Math.random() * .7));
    scene.add(s);
    addFx({ t: life, update(dt) {
      this.t -= dt;
      s.position.addScaledVector(v, dt);
      v.y -= 20 * dt;
      s.material.opacity = Math.max(0, this.t / life);
      if (this.t <= 0) { scene.remove(s); s.material.dispose(); return false; }
      return true;
    }});
  }
}

/* falling glass shards for frame breaks */
function glassShards(pos, n = 10) {
  for (let i = 0; i < n; i++) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(.2 + Math.random() * .3, .3 + Math.random() * .5, .05),
      new THREE.MeshBasicMaterial({ color: 0xcfeaff, transparent: true, opacity: .8 }));
    m.position.copy(pos).add(new THREE.Vector3((Math.random() - .5) * 2.4, (Math.random() - .5) * 4, (Math.random() - .5) * .8));
    scene.add(m);
    const v = new THREE.Vector3((Math.random() - .5) * 8, 2 + Math.random() * 5, (Math.random() - .5) * 8);
    const av = (Math.random() - .5) * 12;
    addFx({ t: .9, update(dt) {
      this.t -= dt;
      v.y -= 24 * dt;
      m.position.addScaledVector(v, dt);
      m.rotation.x += av * dt; m.rotation.z += av * dt;
      m.material.opacity = Math.min(.8, this.t * 1.6);
      if (this.t <= 0) { scene.remove(m); m.material.dispose(); return false; }
      return true;
    }});
  }
}

function ringWave(pos, color, maxR = 10, life = .5, up = false) {
  const geo = new THREE.TorusGeometry(1, .12, 8, 40);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
  const m = new THREE.Mesh(geo, mat);
  m.position.copy(pos);
  if (!up) m.rotation.x = -Math.PI / 2;
  scene.add(m);
  addFx({ t: life, update(dt) {
    this.t -= dt;
    const p = 1 - this.t / life;
    m.scale.setScalar(1 + p * maxR);
    mat.opacity = 1 - p;
    if (this.t <= 0) { scene.remove(m); geo.dispose(); mat.dispose(); return false; }
    return true;
  }});
}

function damageNumber(pos, text, color = "#fff") {
  const c = document.createElement("canvas");
  c.width = 192; c.height = 64;
  const g = c.getContext("2d");
  let size = 38;
  g.font = `bold ${size}px Arial`;
  while (size > 16 && g.measureText(text).width > 182) {
    size -= 2;
    g.font = `bold ${size}px Arial`;
  }
  g.textAlign = "center";
  g.lineWidth = 6; g.strokeStyle = "rgba(0,0,0,.85)";
  g.strokeText(text, 96, 44); g.fillStyle = color; g.fillText(text, 96, 44);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), transparent: true, depthWrite: false }));
  s.scale.set(5.1, 1.7, 1);
  s.position.copy(pos).add(new THREE.Vector3((Math.random() - .5) * 1.4, 1 + Math.random(), (Math.random() - .5) * 1.4));
  scene.add(s);
  addFx({ t: .8, update(dt) {
    this.t -= dt;
    s.position.y += 2.4 * dt;
    s.material.opacity = Math.min(1, this.t * 2.5);
    if (this.t <= 0) { scene.remove(s); s.material.map.dispose(); s.material.dispose(); return false; }
    return true;
  }});
}

function ghostAfterimage(rig, color = 0x66aaff, alpha = .5) {
  const g = new THREE.Group();
  rig.root.updateMatrixWorld(true);
  rig.root.traverse(o => {
    if (o.isMesh && o.visible) {
      const m = new THREE.Mesh(o.geometry, new THREE.MeshBasicMaterial({
        color, transparent: true, opacity: alpha, blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      o.getWorldPosition(m.position);
      o.getWorldQuaternion(m.quaternion);
      o.getWorldScale(m.scale);
      g.add(m);
    }
  });
  scene.add(g);
  addFx({ t: .3, update(dt) {
    this.t -= dt;
    g.children.forEach(m => m.material.opacity = this.t / .3 * alpha);
    if (this.t <= 0) {
      g.children.forEach(m => m.material.dispose());
      scene.remove(g); return false;
    }
    return true;
  }});
}

let shakeMag = 0;
function addShake(m) { shakeMag = Math.max(shakeMag, m); }
function hitstop(t) { hitstopT = Math.max(hitstopT, t); }

/* ---------------- audio ---------------- */
let AC = null;
function audio() {
  if (!AC) { try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {} }
  if (AC && AC.state === "suspended") AC.resume();
  return AC;
}
function tone(f, dur, type = "square", vol = .1, slide = 0, delay = 0) {
  const ac = audio(); if (!ac) return;
  const t0 = ac.currentTime + delay;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type; o.frequency.setValueAtTime(f, t0);
  if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, f + slide), t0 + dur);
  g.gain.setValueAtTime(vol, t0);
  g.gain.exponentialRampToValueAtTime(.001, t0 + dur);
  o.connect(g).connect(ac.destination);
  o.start(t0); o.stop(t0 + dur + .05);
}
function noiseBurst(dur = .25, vol = .18, freq = 800, type = "lowpass") {
  const ac = audio(); if (!ac) return;
  const n = ac.sampleRate * dur;
  const buf = ac.createBuffer(1, n, ac.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
  const src = ac.createBufferSource(); src.buffer = buf;
  const f = ac.createBiquadFilter(); f.type = type; f.frequency.value = freq;
  const g = ac.createGain(); g.gain.value = vol;
  src.connect(f).connect(g).connect(ac.destination);
  src.start();
}
const sfx = {
  punch()   { noiseBurst(.09, .14, 1200); tone(140, .07, "square", .1, -60); },
  palm()    { noiseBurst(.12, .2, 600); tone(90, .12, "sine", .16, -30); },
  kick()    { noiseBurst(.14, .18, 900); tone(120, .12, "square", .12, -70); },
  whoosh()  { noiseBurst(.16, .08, 500); },
  dash()    { noiseBurst(.14, .1, 700); tone(300, .12, "sine", .05, 250); },
  redFire() { noiseBurst(.3, .2, 1000); tone(180, .35, "sawtooth", .12, 300); },
  redBoom() { noiseBurst(.5, .3, 700); tone(70, .5, "sawtooth", .2, -40); tone(140, .4, "square", .08, -80); },
  raise()   { tone(500, .5, "sine", .06, 500); },
  shatter() {
    noiseBurst(.35, .22, 2400, "highpass");
    tone(2100, .18, "sine", .07, -1300);
    tone(1500, .22, "triangle", .06, -900, .04);
    tone(2600, .14, "sine", .05, -1500, .08);
  },
  frame() {
    tone(1400, .4, "sine", .08, 200);
    tone(2100, .5, "sine", .05, 150, .05);
    noiseBurst(.2, .08, 3000, "highpass");
  },
  stab()    { noiseBurst(.1, .18, 2600, "highpass"); tone(900, .08, "sawtooth", .08, -500); },
  bleed()   { tone(220, .1, "sine", .08, -80); },
  tpDone()  { tone(900, .16, "sine", .09, -520); noiseBurst(.12, .08, 1800, "highpass"); },
  hurt()    { tone(200, .2, "sawtooth", .12, -120); },
};

/* ---------------- collision ---------------- */
function collideWorld(pos, radius) {
  if (window.JJMAP && JJMAP.id === 'jjs') return JJMAP.collide(pos, radius);
  pos.x = Math.max(-ARENA, Math.min(ARENA, pos.x));
  pos.z = Math.max(-ARENA, Math.min(ARENA, pos.z));
  for (const b of buildingAABBs) {
    const cx = Math.max(b.minX, Math.min(pos.x, b.maxX));
    const cz = Math.max(b.minZ, Math.min(pos.z, b.maxZ));
    const dx = pos.x - cx, dz = pos.z - cz;
    const d2 = dx * dx + dz * dz;
    if (d2 < radius * radius) {
      if (d2 > 1e-6) {
        const d = Math.sqrt(d2);
        pos.x = cx + dx / d * radius;
        pos.z = cz + dz / d * radius;
      } else {
        const pushL = pos.x - b.minX + radius, pushR = b.maxX - pos.x + radius;
        const pushB = pos.z - b.minZ + radius, pushF = b.maxZ - pos.z + radius;
        const m = Math.min(pushL, pushR, pushB, pushF);
        if (m === pushL) pos.x = b.minX - radius;
        else if (m === pushR) pos.x = b.maxX + radius;
        else if (m === pushB) pos.z = b.minZ - radius;
        else pos.z = b.maxZ + radius;
      }
    }
  }
}

/* ---------------- glass frames (Projection Sorcery) ---------------- */
function makeGlassPane() {
  const grp = new THREE.Group();
  const glass = new THREE.Mesh(new THREE.BoxGeometry(3.4, 6, .22),
    new THREE.MeshBasicMaterial({ color: 0x9fd4ff, transparent: true, opacity: .22, depthWrite: false }));
  grp.add(glass);
  const fm = new THREE.MeshBasicMaterial({ color: 0xeef7ff });
  const mk = (w, h, x, y) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, .26), fm);
    m.position.set(x, y, 0); grp.add(m);
  };
  mk(3.6, .14, 0, 3); mk(3.6, .14, 0, -3); mk(.14, 6.1, 1.73, 0); mk(.14, 6.1, -1.73, 0);
  /* crack lines on the glass */
  const lm = new THREE.MeshBasicMaterial({ color: 0xdff2ff, transparent: true, opacity: .5 });
  for (let i = 0; i < 4; i++) {
    const l = new THREE.Mesh(new THREE.BoxGeometry(.04, 2 + Math.random() * 2.4, .24), lm);
    l.position.set((Math.random() - .5) * 2.4, (Math.random() - .5) * 3.6, 0);
    l.rotation.z = (Math.random() - .5) * 1.4;
    grp.add(l);
  }
  return grp;
}

