/* ---------------- enemies ---------------- */
/* attack dummy M1-M4 swing poses: guard stance, jab L, jab R, hook L, heavy straight */
function poseDummySwing(r, n, st) {
  r.shoulderL.rotation.x = -.55; r.shoulderR.rotation.x = -.55;
  r.elbowL.rotation.x = -1.25;  r.elbowR.rotation.x = -1.25;
  r.spine.rotation.x = -.08;
  r.kneeL.rotation.x = .18; r.kneeR.rotation.x = .18;
  r.hipL.rotation.z = -.05; r.hipR.rotation.z = .05;
  if (n < 0) return;
  const ext = ease(clamp01(st / .16)) * (1 - ease(clamp01((st - .22) / .26)));
  switch (n) {
    case 0:   /* left jab */
      r.shoulderL.rotation.x = -.55 - 1.2 * ext;
      r.elbowL.rotation.x = -1.25 + 1.15 * ext;
      r.spine.rotation.y = .32 * ext;
      break;
    case 1:   /* right jab */
      r.shoulderR.rotation.x = -.55 - 1.2 * ext;
      r.elbowR.rotation.x = -1.25 + 1.15 * ext;
      r.spine.rotation.y = -.32 * ext;
      break;
    case 2:   /* left hook */
      r.shoulderL.rotation.x = -.55 - .5 * ext;
      r.shoulderL.rotation.z = -.95 * ext;
      r.elbowL.rotation.x = -1.25 + .6 * ext;
      r.spine.rotation.y = .6 * ext;
      r.hips.rotation.y = .25 * ext;
      break;
    case 3: { /* heavy straight with a lunge */
      const wind = ease(clamp01(st / .14));
      const go = ease(clamp01((st - .14) / .14)) * (1 - ease(clamp01((st - .46) / .3)));
      r.spine.rotation.y = .45 * wind - 1.05 * go * wind;
      r.shoulderR.rotation.x = -.3 - 1.55 * go;
      r.shoulderR.rotation.z = .25 * wind * (1 - go);
      r.elbowR.rotation.x = -1.5 + 1.45 * go;
      r.spine.rotation.x = -.08 - .22 * go;
      r.kneeR.rotation.x = .18 + .35 * go;
      r.hips.position.y = r.hipsBaseY - .14 * go;
      break;
    }
  }
}

let enemies = [];
const debris = [];
class Enemy {
  constructor(x, z, kind) {
    this.kind = kind;                 // "dummy": stands still · "attacker": rooted, loops M1-M4
    this.rig = makeAnimeRig(kind === "attacker" ? ATTACK_CFG : DUMMY_CFG);
    if (kind === "attacker") {
      const band = boxMesh(.96, .14, .96, 0xd83a2a);
      band.position.y = .78;
      this.rig.head.add(band);
    }
    this.spawn = new THREE.Vector3(x, 0, z);
    this.pos = this.spawn.clone();
    this.vel = new THREE.Vector3();
    this.hp = this.maxHp = kind === "attacker" ? 120 : 100;
    this.onGround = true;
    this.stunT = 0; this.flung = false;
    this.anchorT = 0; this.anchorPos = new THREE.Vector3();
    this.lockT = 0;
    this.swing = -1; this.swingT = 0; this.hitAt = null;
    this.react = null;
    this.dead = false; this.respawnT = 0;
    this.animT = Math.random() * 9;
    this.facing = 0;
    /* projection sorcery */
    this.proj = 0;             // 0..100 meter
    this.frameT = 0;           // frozen in glass frame
    this.frameOwner = null;
    this.frameMesh = null;
    this.bleed = 0;            // bleed stacks 0..3
    this.hemo = null;          // { ticks, acc }
    this.vis24 = 0;
    /* bars */
    this.hpC = document.createElement("canvas");
    this.hpC.width = 96; this.hpC.height = 26;
    this.hpTex = new THREE.CanvasTexture(this.hpC);
    this.hpSpr = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.hpTex, transparent: true, depthWrite: false }));
    this.hpSpr.scale.set(4, 1.1, 1);
    this.rig.root.add(this.hpSpr);
    this.hpSpr.position.y = 6.5;
    this.drawBars();
    scene.add(this.rig.root);
  }
  drawBars() {
    const g = this.hpC.getContext("2d");
    g.clearRect(0, 0, 96, 26);
    g.fillStyle = "rgba(0,0,0,.6)"; g.fillRect(0, 0, 96, 12);
    g.fillStyle = this.kind === "attacker" ? "#ff6a5a" : "#48d868";
    g.fillRect(2, 2, 92 * Math.max(0, this.hp / this.maxHp), 8);
    /* projection meter under hp */
    if (this.proj > 0 || this.frameT > 0) {
      g.fillStyle = "rgba(0,0,0,.6)"; g.fillRect(0, 13, 96, 7);
      g.fillStyle = "#7fd4ff";
      g.fillRect(1, 14, 94 * clamp01(this.proj / 100), 5);
    }
    /* bleed pips */
    for (let i = 0; i < this.bleed; i++) {
      g.fillStyle = "#ff3b4e";
      g.fillRect(2 + i * 9, 21, 7, 5);
    }
    this.hpTex.needsUpdate = true;
  }
  applyProj(amount, byPlayer = true) {
    if (this.dead || this.frameT > 0) return;
    this.proj = Math.min(130, this.proj + amount);
    if (this.proj >= 100) this.enterFrame(byPlayer ? "player" : null);
    this.drawBars();
  }
  enterFrame(owner) {
    this.proj = 0;
    this.frameT = 3;
    this.react = null;
    this.frameOwner = owner;
    this.anchorT = 0; this.lockT = 0; this.flung = false;
    this.vel.set(0, 0, 0);
    this.stunT = Math.max(this.stunT, .3);
    this.rig.root.scale.z = .12;                    // flattened into the film frame
    this.rig.body.rotation.set(0, 0, 0);
    this.frameMesh = makeGlassPane();
    this.frameMesh.position.copy(this.pos).add(new THREE.Vector3(0, 3, 0));
    this.frameMesh.rotation.y = this.facing;
    scene.add(this.frameMesh);
    sfx.frame();
    addShake(.25);
    ringWave(this.pos.clone().add(new THREE.Vector3(0, 3, 0)), 0x9fd8ff, 5, .5, true);
    damageNumber(this.pos.clone().add(new THREE.Vector3(0, 6, 0)), "FRAMED!", "#9fd8ff");
    this.drawBars();
  }
  unframe(shattered) {
    this.frameT = 0;
    this.frameOwner = null;
    this.rig.root.scale.z = 1;
    if (this.frameMesh) {
      if (shattered) {
        glassShards(this.frameMesh.position, 12);
        spark(this.frameMesh.position, 0xcfeaff, 10, 16, 1.4);
        sfx.shatter();
      }
      scene.remove(this.frameMesh);
      this.frameMesh.traverse(o => { if (o.isMesh) o.material.dispose?.(); });
      this.frameMesh = null;
    }
  }
  damage(amount, knock, opts = {}) {
    if (this.dead) return;
    if (this.frameT > 0) {
      if (!opts.noFrameBonus && this.frameOwner === "player") {
        amount *= 3;
        damageNumber(this.pos.clone().add(new THREE.Vector3(0, 6.2, 0)), "BREAK x3", "#cfeaff");
      }
      this.unframe(true);
    }
    this.hp -= amount;
    if (opts.react) this.react = { type: opts.react, t: 0, dur: opts.reactDur ?? .5, side: opts.side ?? (Math.random() < .5 ? -1 : 1) };
    this.drawBars();
    damageNumber(this.pos.clone().add(new THREE.Vector3(0, 5.4, 0)), Math.round(amount), opts.color || "#fff");
    spark(this.pos.clone().add(new THREE.Vector3(0, 3.2, 0)), opts.spark || 0xffffff, 5, 12);
    if (knock) {
      this.vel.add(knock);
      if (knock.lengthSq() > 300) { this.flung = true; this.onGround = false; this.anchorT = 0; this.lockT = 0; }
    }
    this.stunT = Math.max(this.stunT, opts.stun ?? .25);
    if (this.hp <= 0) this.die();
  }
  directDamage(n, color, canKill = false) {
    if (this.dead) return;
    if (!canKill && this.hp - n < 1) n = Math.max(0, this.hp - 1);
    if (n <= 0) return;
    this.hp -= n;
    damageNumber(this.pos.clone().add(new THREE.Vector3(0, 5, 0)), Math.round(n), color);
    this.drawBars();
    if (this.hp <= 0) this.die();
  }
  die() {
    this.dead = true;
    this.respawnT = 4;
    this.unframe(false);
    this.rig.root.updateMatrixWorld(true);
    const meshes = [];
    this.rig.root.traverse(o => { if (o.isMesh) meshes.push(o); });
    for (const o of meshes) {
      const m = new THREE.Mesh(o.geometry, o.material.clone());
      m.material.transparent = true;
      o.getWorldPosition(m.position);
      o.getWorldQuaternion(m.quaternion);
      m.castShadow = true;
      scene.add(m);
      debris.push({
        mesh: m, t: 1.4,
        vel: new THREE.Vector3((Math.random() - .5) * 16, 8 + Math.random() * 10, (Math.random() - .5) * 16),
        av: new THREE.Vector3(Math.random() * 8, Math.random() * 8, Math.random() * 8),
      });
    }
    scene.remove(this.rig.root);
  }
  respawn() {
    this.dead = false;
    this.hp = this.maxHp;
    this.pos.copy(this.spawn);
    this.vel.set(0, 0, 0);
    this.flung = false; this.stunT = 0; this.anchorT = 0; this.lockT = 0;
    this.proj = 0; this.bleed = 0; this.hemo = null;
    this.react = null; this.swing = -1; this.swingT = 0; this.hitAt = null;
    this.rig.body.rotation.set(0, 0, 0);
    this.rig.root.scale.z = 1;
    this.drawBars();
    scene.add(this.rig.root);
    spark(this.spawn.clone().add(new THREE.Vector3(0, 3, 0)), 0xaaddff, 10, 10);
  }
  /* per-skill hit reaction animations, layered over the current pose */
  applyReact(dt) {
    if (!this.react) return;
    const rc = this.react;
    rc.t += dt;
    if (rc.t >= rc.dur) { this.react = null; return; }
    const r = this.rig;
    const k = rc.t / rc.dur;
    const env = 1 - ease(k);              // eases out over the duration
    const snap = Math.min(1, rc.t * 14);  // snaps in fast
    const e2 = env * snap;
    const t = this.animT;
    switch (rc.type) {
      case "head":      /* head snapped back by a jab */
        r.neck.rotation.x = -.6 * e2;
        r.neck.rotation.z = .25 * rc.side * e2;
        r.spine.rotation.x = -.22 * e2;
        r.spine.rotation.y = .3 * rc.side * e2;
        r.shoulderL.rotation.x = .3 * e2; r.shoulderR.rotation.x = .3 * e2;
        break;
      case "gut":       /* doubled over clutching the stomach */
        r.spine.rotation.x = .8 * e2;
        r.neck.rotation.x = .35 * e2;
        r.shoulderL.rotation.x = -1.15 * e2; r.shoulderR.rotation.x = -1.15 * e2;
        r.shoulderL.rotation.z = .3 * e2;    r.shoulderR.rotation.z = -.3 * e2;
        r.elbowL.rotation.x = -1.5 * e2;     r.elbowR.rotation.x = -1.5 * e2;
        r.kneeL.rotation.x = .5 * e2;        r.kneeR.rotation.x = .5 * e2;
        r.hips.position.y = r.hipsBaseY - .28 * e2;
        break;
      case "stab":      /* clutch the wound, tremble, sag down */
        r.spine.rotation.x = (.55 + .25 * Math.sin(Math.min(1, k * 2) * Math.PI)) * snap;
        r.spine.rotation.z = Math.sin(t * 26) * .06 * env;
        r.neck.rotation.x = .5 * snap * (1 - k * .4);
        r.shoulderL.rotation.x = -1.2 * snap; r.shoulderR.rotation.x = -1.3 * snap;
        r.shoulderL.rotation.z = .35 * snap;  r.shoulderR.rotation.z = -.35 * snap;
        r.elbowL.rotation.x = -1.55 * snap;   r.elbowR.rotation.x = -1.6 * snap;
        r.kneeL.rotation.x = (.35 + .3 * k) * snap;
        r.kneeR.rotation.x = (.45 + .3 * k) * snap;
        r.hips.position.y = r.hipsBaseY - (.2 + .25 * k) * snap;
        break;
      case "pummel":    /* jerked around by a rapid barrage */
        r.spine.rotation.x = -.08 + Math.sin(t * 38) * .14;
        r.spine.rotation.y = Math.sin(t * 31) * .18;
        r.neck.rotation.x = Math.sin(t * 33 + 1) * .3 - .1;
        r.neck.rotation.z = Math.sin(t * 27) * .14;
        r.shoulderL.rotation.x = .5 + Math.sin(t * 29) * .25;
        r.shoulderR.rotation.x = .5 + Math.cos(t * 26) * .25;
        r.shoulderL.rotation.z = -.25; r.shoulderR.rotation.z = .25;
        r.elbowL.rotation.x = -.3; r.elbowR.rotation.x = -.3;
        r.hips.position.y = r.hipsBaseY - .1 + Math.sin(t * 40) * .03;
        break;
      case "stagger":   /* knocked back onto the heels, arms windmilling */
        r.spine.rotation.x = -.42 * e2;
        r.neck.rotation.x = -.35 * e2;
        r.shoulderL.rotation.x = -.9 * e2 + Math.sin(t * 16) * .25 * env;
        r.shoulderR.rotation.x = -.9 * e2 + Math.cos(t * 15) * .25 * env;
        r.shoulderL.rotation.z = -.5 * e2; r.shoulderR.rotation.z = .5 * e2;
        r.hipL.rotation.x = -.35 * e2; r.kneeL.rotation.x = .2 * snap;
        r.hipR.rotation.x = .25 * e2;  r.kneeR.rotation.x = .45 * e2;
        break;
    }
  }
  /* 24 FPS rule: entities under Projection render position at 24 Hz */
  syncVis(dt) {
    if (this.proj > 0) {
      this.vis24 += dt;
      if (this.vis24 < 1 / 24) return;
      this.vis24 = 0;
    }
    this.rig.root.position.copy(this.pos);
  }
  update(dt) {
    if (this.dead) {
      this.respawnT -= dt;
      if (this.respawnT <= 0) this.respawn();
      return;
    }
    /* frozen in a glass frame */
    if (this.frameT > 0) {
      this.frameT -= dt;
      if (this.frameT <= 0) this.unframe(false);
      return;
    }
    const r = this.rig;
    this.animT += dt;
    resetPose(r);

    /* projection meter passive drain (2%/s, 1.3%/s while bleeding) */
    if (this.proj > 0) {
      this.proj = Math.max(0, this.proj - dt * (this.bleed > 0 ? 1.3 : 2));
      if (Math.random() < dt * 4) this.drawBars();
    }
    /* hemorrhage damage over time (paused by frames; can't kill) */
    if (this.hemo) {
      this.hemo.acc += dt;
      while (this.hemo && this.hemo.acc >= .5) {
        this.hemo.acc -= .5;
        if (this.bleed <= 0) { this.hemo = null; break; }
        this.directDamage(1, "#ff6677");
        if (Math.random() < .5) spark(this.pos.clone().add(new THREE.Vector3(0, 2.4, 0)), 0xd82a3c, 2, 5, .9);
        this.hemo.ticks++;
        if (this.hemo.ticks >= 39) { this.bleed = 0; this.hemo = null; this.drawBars(); }
      }
    }

    if (this.anchorT > 0) {
      /* anchored mid-air: arched back, limbs dangling and slowly flailing */
      this.anchorT -= dt;
      this.vel.set(0, 0, 0);
      this.pos.lerp(this.anchorPos, Math.min(1, dt * 12));
      const fl = this.animT * 3.2;
      r.body.rotation.x = Math.max(r.body.rotation.x - dt * 1.8, -.42);
      r.neck.rotation.x = -.5;
      r.shoulderL.rotation.z = -1.2 + Math.sin(fl) * .25;
      r.shoulderR.rotation.z = 1.2 + Math.sin(fl + 1.4) * .25;
      r.shoulderL.rotation.x = -.4 + Math.sin(fl * 1.3) * .3;
      r.shoulderR.rotation.x = -.4 + Math.cos(fl * 1.1) * .3;
      r.elbowL.rotation.x = -.5; r.elbowR.rotation.x = -.5;
      r.hipL.rotation.x = -.55 + Math.sin(fl + .8) * .3;
      r.hipR.rotation.x = .25 + Math.sin(fl + 2.6) * .3;
      r.kneeL.rotation.x = .9; r.kneeR.rotation.x = .7;
      this.syncVis(dt);
      if (Math.random() < dt * 8) spark(this.pos.clone().add(new THREE.Vector3(0, 3, 0)), 0xbfe2ff, 1, 4, .8);
      return;
    }

    if (this.lockT > 0) {
      this.lockT -= dt;
      this.vel.set(0, 0, 0);
      r.body.rotation.x = .06;
      r.shoulderL.rotation.x = .35; r.shoulderR.rotation.x = .35;
      r.elbowL.rotation.x = -.5; r.elbowR.rotation.x = -.5;
      r.kneeL.rotation.x = .15; r.kneeR.rotation.x = .15;
      this.applyReact(dt);
      this.syncVis(dt);
      r.root.rotation.y = this.facing;
      return;
    }

    const previousY = this.pos.y;
    this.vel.y -= 30 * dt;
    this.pos.addScaledVector(this.vel, dt);
    if (resolveActorWorld(this, previousY, 1)) {
      if (this.flung) {
        this.flung = false;
        this.stunT = Math.max(this.stunT, .6);
        ringWave(this.pos.clone().add(new THREE.Vector3(0, .2, 0)), 0xccccff, 4, .35);
      }
      this.onGround = true;
      this.vel.x *= Math.pow(.001, dt);
      this.vel.z *= Math.pow(.001, dt);
    }

    if (this.flung) {
      /* tumbling ragdoll with flailing limbs */
      r.body.rotation.x += 9 * dt;
      r.body.rotation.z += 5 * dt;
      const fp = this.animT * 13;
      r.shoulderL.rotation.x = Math.sin(fp) * 1.5;
      r.shoulderR.rotation.x = Math.sin(fp + 2.1) * 1.5;
      r.shoulderL.rotation.z = -.6; r.shoulderR.rotation.z = .6;
      r.elbowL.rotation.x = -.5 + Math.sin(fp * 1.3) * .4;
      r.elbowR.rotation.x = -.5 + Math.cos(fp * 1.2) * .4;
      r.hipL.rotation.x = Math.sin(fp + 1) * 1.1;
      r.hipR.rotation.x = Math.sin(fp + 3.2) * 1.1;
      r.kneeL.rotation.x = .6 + Math.sin(fp * 1.4) * .4;
      r.kneeR.rotation.x = .6 + Math.cos(fp * 1.5) * .4;
      r.neck.rotation.x = Math.sin(fp * .9) * .4;
    } else if (this.stunT > 0) {
      this.stunT -= dt;
      r.body.rotation.x *= .85; r.body.rotation.z *= .85;
      r.body.rotation.x += Math.sin(this.animT * 30) * .05;
      r.neck.rotation.z = Math.sin(this.animT * 24) * .12;
      r.shoulderL.rotation.x = .3; r.shoulderR.rotation.x = .3;
      r.elbowL.rotation.x = -.6; r.elbowR.rotation.x = -.6;
      r.kneeL.rotation.x = .2; r.kneeR.rotation.x = .2;
      this.applyReact(dt);
    } else {
      r.body.rotation.x *= .8; r.body.rotation.z *= .8;
      if (this.kind === "attacker") {
        /* attack dummy: rooted in place, endlessly cycling its M1 combo */
        const toP = player.pos.clone().sub(this.pos); toP.y = 0;
        if (!player.dead && toP.lengthSq() > .01) {
          const want = Math.atan2(toP.x, toP.z);
          let dyaw = want - this.facing;
          while (dyaw > Math.PI) dyaw -= Math.PI * 2;
          while (dyaw < -Math.PI) dyaw += Math.PI * 2;
          this.facing += dyaw * Math.min(1, dt * 6);
        }
        this.swingT += dt;
        const gap = this.swing === 3 ? 1.15 : .62;
        if (this.swingT >= gap) {
          this.swingT = 0;
          this.swing = (this.swing + 1) % 4;
          this.hitAt = .2;
          if (player.pos.distanceTo(this.pos) < 14) sfx.whoosh();
          /* spending a "move" burns one bleed stack, at a price */
          if (this.swing === 3 && this.bleed > 0) {
            this.bleed--;
            this.directDamage(4, "#ff3b4e");
            sfx.bleed();
            this.drawBars();
            if (this.bleed <= 0) this.hemo = null;
          }
        }
        if (this.hitAt !== null) {
          this.hitAt -= dt;
          if (this.hitAt <= 0) {
            this.hitAt = null;
            const d2 = player.pos.clone().sub(this.pos); d2.y = 0;
            if (!player.dead && d2.length() < 3.4) {
              const heavy = this.swing === 3;
              hurtPlayer(heavy ? 6 : 3, d2.normalize().multiplyScalar(heavy ? 12 : 5).setY(heavy ? 4 : 1.5));
            }
          }
        }
        poseDummySwing(r, this.swing, this.swingT);
        r.root.rotation.y = this.facing;
      } else {
        /* normal dummy: just stands there */
        const brr = Math.sin(this.animT * 1.6);
        r.shoulderL.rotation.x = .05 + brr * .04;
        r.shoulderR.rotation.x = .05 - brr * .04;
        r.elbowL.rotation.x = r.elbowR.rotation.x = -.15;
        r.spine.rotation.x = .03 + brr * .02;
        r.neck.rotation.y = Math.sin(this.animT * .4) * .2;
        r.root.rotation.y = this.facing;
      }
      this.applyReact(dt);
    }
    this.syncVis(dt);
  }
}
{
  const spots = [
    [10, -8, "dummy"], [-12, -14, "dummy"], [18, 6, "dummy"], [-20, 8, "dummy"],
    [4, -26, "dummy"], [-6, 18, "dummy"],
    [28, -18, "attacker"], [-28, -20, "attacker"], [24, 22, "attacker"], [-24, 24, "attacker"],
  ];
  for (const [x, z, k] of spots) enemies.push(new Enemy(x, z, k));
}

function enemiesNear(pos, radius, dir = null, cosAngle = -1) {
  const out = [];
  for (const e of enemies) {
    if (e.dead) continue;
    const to = e.pos.clone().add(new THREE.Vector3(0, 2.5, 0)).sub(pos);
    const d = to.length();
    if (d > radius) continue;
    if (dir && d > .01) {
      to.normalize();
      if (to.dot(dir) < cosAngle) continue;
    }
    out.push(e);
  }
  return out;
}
function nearestFrontEnemy(range, cosAngle) {
  const dir = camForward();
  const origin = player.pos.clone().add(new THREE.Vector3(0, 2.5, 0));
  const list = enemiesNear(origin, range, dir, cosAngle);
  list.sort((a, b) => a.pos.distanceTo(player.pos) - b.pos.distanceTo(player.pos));
  return list[0] || null;
}
function cursorTarget(minCos = .94, maxDist = 60) {
  const camDir = new THREE.Vector3();
  camera.getWorldDirection(camDir);
  let best = null, bestCos = minCos;
  for (const e of enemies) {
    if (e.dead) continue;
    const v = e.pos.clone().add(new THREE.Vector3(0, 2.8, 0)).sub(camera.position);
    const d = v.length();
    if (d > maxDist) continue;
    v.normalize();
    const c = v.dot(camDir);
    if (c > bestCos) { bestCos = c; best = e; }
  }
  return best;
}
/* aim a ground position with the cursor, clamped to maxDist studs from the player */
function aimPoint(maxDist = 50) {
  const d = new THREE.Vector3();
  camera.getWorldDirection(d);
  let pt;
  if (d.y < -.03) {
    const t = camera.position.y / -d.y;
    pt = camera.position.clone().addScaledVector(d, t);
  } else {
    pt = player.pos.clone().addScaledVector(camForward(), maxDist);
  }
  pt.y = 0;
  const v = pt.sub(player.pos);
  const L = v.length();
  if (L > maxDist) v.multiplyScalar(maxDist / L);
  const dest = player.pos.clone().add(v);
  collideWorld(dest, 1);
  return dest;
}

/* ---------------- player damage / projection ---------------- */
const vignette = document.getElementById("vignette");
let vigT = 0;
function hurtPlayer(amount, knock) {
  if (player.dead || player.iframes > 0) return;
  player.hp -= amount;
  vigT = .5;
  sfx.hurt();
  addShake(.25);
  if (knock && player.frameT <= 0) player.vel.add(knock);
  spark(player.pos.clone().add(new THREE.Vector3(0, 3, 0)), 0xff4455, 5, 10);
  if (player.hp <= 0) {
    player.hp = 0;
    player.dead = true;
    player.deathT = 2.5;
    player.action = null;
    unframePlayer(false);
    showSplash("DEFEATED", "RESPAWNING...", "#ff3355");
  }
}
function applyProjPlayer(amount) {
  if (player.frameT > 0) return;
  player.proj = Math.min(130, player.proj + amount);
  damageNumber(player.pos.clone().add(new THREE.Vector3(0, 5.6, 0)), "+" + Math.round(amount) + "%", "#7fd4ff");
  if (player.proj >= 100) framePlayer();
}
function framePlayer() {
  player.proj = 0;
  player.frameT = 3;
  player.action = null;
  player.vel.set(0, 0, 0);
  player.rig.root.scale.z = .12;
  player.frameMesh = makeGlassPane();
  player.frameMesh.position.copy(player.pos).add(new THREE.Vector3(0, 3, 0));
  player.frameMesh.rotation.y = player.facing;
  scene.add(player.frameMesh);
  sfx.frame();
  addShake(.3);
  showSplash("FRAMED!", "24 FPS", "#7fd4ff");
}
function unframePlayer(shattered) {
  player.frameT = 0;
  player.rig.root.scale.z = 1;
  if (player.frameMesh) {
    if (shattered) { glassShards(player.frameMesh.position, 10); sfx.shatter(); }
    scene.remove(player.frameMesh);
    player.frameMesh = null;
  }
}

/* ---------------- camera ---------------- */
let camYaw = Math.PI, camPitch = .22;
let camShoulder = 0;
let mapView = null;
function camForward() {
  return new THREE.Vector3(-Math.sin(camYaw), 0, -Math.cos(camYaw)).normalize();
}
function updateCamera(dt) {
  if (mapView) {
    camera.position.set(mapView.x, mapView.y, mapView.z);
    camera.lookAt(mapView.lx, mapView.ly, mapView.lz);
    return;
  }
  const fwd = camForward();
  const dist = 9.5, height = 4.4;
  const target = player.pos.clone().add(new THREE.Vector3(0, 3, 0));
  camShoulder = lerp(camShoulder, window.JJSHIFT && JJSHIFT.active ? 1.65 : 0, Math.min(1, dt * 12));
  const shoulder = new THREE.Vector3(-fwd.z, 0, fwd.x).multiplyScalar(camShoulder);
  const off = fwd.clone().multiplyScalar(-dist);
  off.y = height + Math.sin(camPitch) * 7;
  const desired = target.clone().add(off).add(shoulder);
  if (window.JJMAP && JJMAP.id === 'jjs') {
    const fraction = JJJJS.ray(target, desired, .28);
    desired.lerpVectors(target, desired.clone(), fraction);
  } else desired.y = Math.max(1, desired.y);
  camera.position.copy(desired);
  if (shakeMag > 0) {
    camera.position.add(new THREE.Vector3(
      (Math.random() - .5) * shakeMag, (Math.random() - .5) * shakeMag, (Math.random() - .5) * shakeMag));
    shakeMag = Math.max(0, shakeMag - dt * 2.2);
  }
  camera.lookAt(target.clone().add(shoulder).add(new THREE.Vector3(0, camPitch * -4 + 1, 0)));
}

/* ---------------- splash ---------------- */
const splash = document.getElementById("splash");
let splashT = 0;
function showSplash(big, small, glow) {
  splash.querySelector(".big").textContent = big;
  splash.querySelector(".small").textContent = small;
  splash.style.setProperty("--glow", glow);
  splash.style.opacity = 1;
  splashT = 1.6;
}

/* ============================================================
   SKILLS — shared infrastructure
   ============================================================ */
let cds = { m1: 0, red: 0, rapid: 0, twofold: 0, palm: 0, limitless: 0, n1: 0, n2: 0, n3: 0, nr: 0 };
const CD = { red: 6, rapid: 9, twofold: 7, palm: 10, limitless: 6, n1: 8, n2: 9, n3: 10, nr: 7 };
const busy = () => !!player.action || player.frameT > 0 || !!(window.JJFIGHT && JJFIGHT.locked());
function leftOf(dirV) { return new THREE.Vector3(dirV.z, 0, -dirV.x); }
function facingVec() { return new THREE.Vector3(Math.sin(player.facing), 0, Math.cos(player.facing)); }

function holdTargetInFront(tgt, distF) {
  const f = facingVec();
  tgt.lockT = .15;
  tgt.pos.copy(player.pos).addScaledVector(f, distF);
  const support = worldFloor(tgt.pos, player.pos.y + 1.2);
  tgt.pos.y = Number.isFinite(support) ? support : player.pos.y;
  tgt.facing = Math.atan2(-f.x, -f.z);
  return f;
}

/* ----- M1 combo (per character) ----- */
function punch() {
  if (player.dead || cds.m1 > 0 || busy()) return;
  const naoya = player.char === "naoya";
  cds.m1 = naoya ? .27 : .32;
  player.comboReset = .9;
  const n = player.comboN;          // this hit: 0..3, finisher on the 4th
  player.comboN = (n + 1) % 4;
  player.attackT = .2;
  player.attackArm = n % 2;
  sfx.whoosh();
  const dir = camForward();
  const origin = player.pos.clone().add(new THREE.Vector3(0, 2.5, 0));
  const hits = enemiesNear(origin.clone().addScaledVector(dir, 2.2), 2.6);
  const last = n === 3;
  for (const e of hits) {
    if (naoya) {
      /* full set = 8 dmg (2 per hit); final always knocks back w/ evadable stun, bypasses ragdoll */
      const kb = last ? dir.clone().multiplyScalar(16).setY(4) : dir.clone().multiplyScalar(4).setY(.5);
      e.damage(2, kb, { stun: last ? .7 : .3, color: "#cfe4ff",
        react: last ? "stagger" : "head", reactDur: last ? .7 : .4, side: n % 2 ? -1 : 1 });
    } else {
      const kb = last ? dir.clone().multiplyScalar(26).setY(9) : dir.clone().multiplyScalar(5).setY(1);
      e.damage(last ? 12 : 7, kb, { stun: .3, react: "head", reactDur: .4, side: n % 2 ? -1 : 1 });
    }
    hitstop(.05);
    addShake(.12);
    sfx.punch();   // punch_hit_#3, every character
  }
  if (hits.length && last) addShake(naoya ? .2 : .3);
}

/* ----- dash (Q) — Naoya has two charges, any direction ----- */
function doDash() {
  if (player.dead || busy() || player.dashCh < 1) return;
  const fwd = camForward();
  const rightv = new THREE.Vector3(-fwd.z, 0, fwd.x);
  const mv = new THREE.Vector3();
  if (keys["KeyW"]) mv.add(fwd);
  if (keys["KeyS"]) mv.sub(fwd);
  if (keys["KeyD"]) mv.add(rightv);
  if (keys["KeyA"]) mv.sub(rightv);
  if (mv.lengthSq() === 0) mv.copy(fwd);
  mv.normalize();
  player.dashCh -= 1;
  player.vel.x += mv.x * 24;
  player.vel.z += mv.z * 24;
  sfx.dash();
  ghostAfterimage(player.rig, player.char === "naoya" ? 0x9fd8ff : 0x4a7dff);
  setTimeout(() => { if (!player.dead) ghostAfterimage(player.rig, player.char === "naoya" ? 0x9fd8ff : 0x4a7dff); }, 70);
}

/* ============================================================
   GOJO KIT
   ============================================================ */
function castRed() {
  if (player.char !== "gojo" || player.dead || cds.red > 0 || busy()) return;
  cds.red = CD.red;
  player.action = { type: "red", t: 0, dur: .85 };
  sfx.raise();
  addFx({ t: .5, update(dt) {
    this.t -= dt;
    if (Math.random() < .75) {
      const h = handWorld(player.rig.handR);
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: TEX_GLOW, color: 0xff5566, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
      s.position.copy(h).add(new THREE.Vector3((Math.random() - .5) * 4, (Math.random() - .5) * 4, (Math.random() - .5) * 4));
      s.scale.setScalar(.8);
      scene.add(s);
      addFx({ t: .3, update(dt2) {
        this.t -= dt2;
        s.position.lerp(handWorld(player.rig.handR), Math.min(1, dt2 * 12));
        s.material.opacity = this.t / .3;
        if (this.t <= 0) { scene.remove(s); s.material.dispose(); return false; }
        return true;
      }});
    }
    return this.t > 0;
  }});
}
function fireRedOrb() {
  sfx.redFire();
  addShake(.35);
  const dir = new THREE.Vector3();
  camera.getWorldDirection(dir);
  const start = handWorld(player.rig.handR).addScaledVector(dir, .8);

  const grp = new THREE.Group();
  const core = new THREE.Mesh(new THREE.SphereGeometry(.55, 18, 18),
    new THREE.MeshBasicMaterial({ color: 0xff8899, transparent: true, opacity: .95, blending: THREE.AdditiveBlending }));
  const shell = new THREE.Mesh(new THREE.SphereGeometry(.95, 18, 18),
    new THREE.MeshBasicMaterial({ color: 0xff2233, transparent: true, opacity: .45, blending: THREE.AdditiveBlending }));
  const light = new THREE.PointLight(0xff3344, 80, 30);
  grp.add(core, shell, light);
  grp.position.copy(start);
  scene.add(grp);

  addFx({ t: 3, traveled: 0, update(dt) {
    this.t -= dt;
    const step = 52 * dt;
    grp.position.addScaledVector(dir, step);
    this.traveled += step;
    const pl = 1 + Math.sin(performance.now() / 50) * .15;
    core.scale.setScalar(pl); shell.scale.setScalar(pl);
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: TEX_GLOW, color: 0xff4455, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
    s.position.copy(grp.position);
    s.scale.setScalar(1.6);
    scene.add(s);
    addFx({ t: .3, update(dt2) {
      this.t -= dt2;
      s.scale.multiplyScalar(1 - dt2 * 2);
      s.material.opacity = this.t / .3 * .8;
      if (this.t <= 0) { scene.remove(s); s.material.dispose(); return false; }
      return true;
    }});

    let boom = this.traveled >= 40 || grp.position.y <= .5 || this.t <= 0;
    if (!boom) {
      for (const b of buildingAABBs) {
        if (grp.position.x > b.minX - 1 && grp.position.x < b.maxX + 1 &&
            grp.position.z > b.minZ - 1 && grp.position.z < b.maxZ + 1 &&
            grp.position.y < b.h + 1) { boom = true; break; }
      }
    }
    if (!boom && enemiesNear(grp.position, 2.4).length) boom = true;
    if (boom) {
      explodeRed(grp.position.clone());
      scene.remove(grp);
      return false;
    }
    return true;
  }});
}
function explodeRed(pos) {
  sfx.redBoom();
  addShake(1);
  hitstop(.08);
  const blast = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 24),
    new THREE.MeshBasicMaterial({ color: 0xff4455, transparent: true, opacity: .8, blending: THREE.AdditiveBlending }));
  blast.position.copy(pos);
  scene.add(blast);
  addFx({ t: .4, update(dt) {
    this.t -= dt;
    const p = 1 - this.t / .4;
    blast.scale.setScalar(1 + p * 14);
    blast.material.opacity = .8 * (1 - p);
    if (this.t <= 0) { scene.remove(blast); blast.material.dispose(); return false; }
    return true;
  }});
  ringWave(pos, 0xff3344, 16, .5, true);
  ringWave(pos.clone().setY(Math.max(.3, pos.y - 2)), 0xff7788, 19, .6);
  spark(pos, 0xff5566, 28, 30, 2.4);
  for (const e of enemiesNear(pos, 15)) {
    const d = e.pos.clone().add(new THREE.Vector3(0, 2.5, 0)).sub(pos);
    const dist = d.length();
    const kb = d.normalize().multiplyScalar(46 * (1.25 - dist / 15 * .6));
    kb.y = Math.max(kb.y, 15);
    e.damage(14, kb, { color: "#ff5566", spark: 0xff3344 });
  }
  for (const c of crates) {
    const d = c.mesh.position.clone().sub(pos);
    if (d.length() < 15) {
      c.vel.add(d.normalize().multiplyScalar(30).setY(18));
      c.av.set(Math.random() * 10, Math.random() * 10, Math.random() * 10);
    }
  }
}
function castRapid() {
  if (player.char !== "gojo" || player.dead || cds.rapid > 0 || busy()) return;
  const tgt = nearestFrontEnemy(6, .3);
  if (!tgt) return;
  cds.rapid = CD.rapid;
  player.action = { type: "rapid", t: 0, dur: 1.75, tgt, locked: false, acc: 0, fin: false };
  sfx.whoosh();
}
function castTwofold() {
  if (player.char !== "gojo" || player.dead || cds.twofold > 0 || busy()) return;
  cds.twofold = CD.twofold;
  player.action = { type: "tf", t: 0, dur: .98, tgt: null, k1: false, k2: false, miss: false };
  sfx.whoosh();
}
function castPalm() {
  if (player.char !== "gojo" || player.dead || cds.palm > 0 || busy()) return;
  const tgt = nearestFrontEnemy(4.2, .45);
  if (!tgt) return;
  cds.palm = CD.palm;
  player.action = { type: "palm", t: 0, dur: 1.75, tgt, hits: [false, false, false], kicked: false };
  sfx.whoosh();
}
let shatterState = null;
function castLimitless() {
  if (player.char !== "gojo" || player.dead || cds.limitless > 0 || busy()) return false;
  const tgt = cursorTarget();
  if (!tgt) return false;
  cds.limitless = CD.limitless;
  player.action = { type: "lim", t: 0, dur: 1.15, tgt, shattered: false, tp: false };
  sfx.raise();
  return true;
}
function startShatter() {
  const cx = innerWidth / 2, cy = innerHeight / 2;
  const maxR = Math.hypot(cx, cy);
  const cracks = [];
  const N = 16;
  for (let i = 0; i < N; i++) {
    const baseA = i / N * Math.PI * 2 + (Math.random() - .5) * .3;
    let a = baseA, r = 8 + Math.random() * 18;
    const pts = [[Math.cos(a) * r, Math.sin(a) * r]];
    while (r < maxR * 1.08) {
      r += maxR / 6 * (.55 + Math.random() * .75);
      a += (Math.random() - .5) * .45;
      pts.push([Math.cos(a) * r, Math.sin(a) * r]);
    }
    cracks.push({ pts, w: 1.4 + Math.random() * 1.8, ox: Math.cos(baseA), oy: Math.sin(baseA) });
  }
  shatterState = { t: 0, grow: .55, fade: .3, cracks };
  sfx.shatter();
}
function drawShatter(dt) {
  if (!shatterState) return;
  const s = shatterState;
  s.t += dt;
  const g = shCtx;
  g.clearRect(0, 0, shatterCv.width, shatterCv.height);
  const cx = shatterCv.width / 2, cy = shatterCv.height / 2;
  const growP = clamp01(s.t / s.grow);
  const fadeP = clamp01((s.t - s.grow) / s.fade);
  if (fadeP >= 1) { shatterState = null; g.clearRect(0, 0, shatterCv.width, shatterCv.height); return; }

  g.save();
  g.translate(cx, cy);
  if (growP < .3) {
    g.fillStyle = `rgba(210,240,255,${(0.3 - growP) * .9})`;
    g.beginPath(); g.arc(0, 0, 60 + growP * 300, 0, 7); g.fill();
  }
  g.lineCap = "round";
  for (const c of s.cracks) {
    const n = Math.max(2, Math.ceil(c.pts.length * Math.min(1, growP * 1.25)));
    const off = fadeP * 55;
    g.save();
    g.translate(c.ox * off, c.oy * off);
    g.strokeStyle = `rgba(200,232,255,${(1 - fadeP) * .95})`;
    g.lineWidth = c.w;
    g.shadowColor = "rgba(120,200,255,.9)";
    g.shadowBlur = 8;
    g.beginPath();
    g.moveTo(0, 0);
    for (let i = 0; i < n; i++) g.lineTo(c.pts[i][0], c.pts[i][1]);
    g.stroke();
    g.strokeStyle = `rgba(255,255,255,${(1 - fadeP) * .5})`;
    g.lineWidth = c.w * .4;
    g.stroke();
    g.restore();
  }
  g.restore();
}

/* ============================================================
   NAOYA KIT — Projection Sorcery
   ============================================================ */

/* ----- 1: Projection Breaker ----- */
function castN1() {
  if (player.char !== "naoya" || player.dead || cds.n1 > 0 || busy()) return;
  cds.n1 = CD.n1;
  player.action = { type: "n1", t: 0, dur: .8, hit: false, dashed: false, lunged: false };
  sfx.whoosh();
}

/* ----- 2: Tanto stab (+ execution finisher <=14 HP) ----- */
function castN2() {
  if (player.char !== "naoya" || player.dead || cds.n2 > 0 || busy()) return;
  cds.n2 = CD.n2;
  player.action = { type: "n2", t: 0, dur: .78, stabbed: false, fin: false, finN: 0, tgt: null };
  if (player.rig.tanto) player.rig.tanto.visible = true;
  sfx.whoosh();
}

/* ----- 3: You're Not Toji (grab barrage + frame finisher <=25 HP) ----- */
function castN3() {
  if (player.char !== "naoya" || player.dead || cds.n3 > 0 || busy()) return;
  cds.n3 = CD.n3;
  player.action = { type: "n3", t: 0, dur: .62, tgt: null, grabbed: false, fin: false, acc: 0, framed: false, kicked: false };
  sfx.whoosh();
}

/* ----- R: Projection teleport / frame punch ----- */
function castNaoyaR() {
  if (player.char !== "naoya" || player.dead || busy()) return false;
  const tgt = cursorTarget();
  /* frame-punch variant: aim at a framed target while special is off cooldown */
  if (tgt && tgt.frameT > 0 && cds.nr <= 0) {
    player.action = { type: "nrf", t: 0, dur: .5, tgt, hopped: false, punched: false };
    sfx.raise();
    return true;
  }
  if (cds.nr > 0) return false;
  const dest = aimPoint(50);
  const isSecond = player.rWindow > 0;
  if (isSecond && !tgt) return false;
  player.action = { type: "nr", t: 0, dur: .55, from: player.pos.clone(), dest, hop: 0, second: isSecond };
  player.iframes = Math.max(player.iframes, .6);
  sfx.dash();
  return true;
}

/* ============================================================
   ACTION STEP
   ============================================================ */
function stepAction(a, dt) {
  const p = player;
  switch (a.type) {
    /* ---------- GOJO ---------- */
    case "red": {
      if (a.t >= .5 && !a.fired) { a.fired = true; fireRedOrb(); }
      break;
    }
    case "rapid": {
      const tgt = a.tgt;
      if (a.t >= .16 && !a.checked) {
        a.checked = true;
        const d = tgt.pos.clone().sub(p.pos); d.y = 0;
        if (tgt.dead || d.length() > 5.2) { a.miss = true; a.dur = .55; sfx.whoosh(); }
        else {
          a.locked = true;
          p.iframes = Math.max(p.iframes, 1.65);
          sfx.kick();
          addShake(.25);
          tgt.damage(1.5, null, { stun: .4, react: "gut", reactDur: .45 });
        }
      }
      if (a.locked && !tgt.dead && a.t < 1.42) {
        holdTargetInFront(tgt, 2.1);
        if (a.t >= .3) {
          a.acc += dt;
          if (a.acc > .09) {
            a.acc = 0;
            tgt.damage(0.8, null, { stun: .3, react: "pummel", reactDur: .3 });
            sfx.punch();
            addShake(.08);
            spark(tgt.pos.clone().add(new THREE.Vector3((Math.random() - .5) * 1.4, 2.4 + Math.random() * 1.4, (Math.random() - .5) * 1.4)), 0xaad4ff, 3, 12);
          }
        }
      }
      if (a.locked && a.t >= 1.45 && !a.fin) {
        a.fin = true;
        if (!tgt.dead) {
          const f = facingVec();
          tgt.lockT = 0;
          tgt.damage(4, f.multiplyScalar(38).setY(12), { color: "#9fd0ff" });
          sfx.kick();
          addShake(.5);
          hitstop(.06);
        }
      }
      break;
    }
    case "tf": {
      if (a.t >= .18 && !a.k1) {
        a.k1 = true;
        const tgt = nearestFrontEnemy(3.6, .45);
        if (!tgt) { a.miss = true; a.dur = .5; }
        else {
          a.tgt = tgt;
          p.iframes = Math.max(p.iframes, .95);
          tgt.damage(5, null, { stun: .9, color: "#bfe2ff" });
          tgt.anchorT = .8;
          tgt.anchorPos.copy(tgt.pos).setY(3.4);
          tgt.vel.set(0, 0, 0);
          sfx.kick();
          addShake(.3);
          ringWave(tgt.pos.clone().add(new THREE.Vector3(0, 2.4, 0)), 0xbfe2ff, 5, .35, true);
        }
      }
      if (a.t >= .58 && !a.k2 && !a.miss) {
        a.k2 = true;
        p.vel.y = 8.5;
        p.onGround = false;
        const tgt = a.tgt;
        if (tgt && !tgt.dead) {
          const f = facingVec();
          tgt.anchorT = 0;
          tgt.damage(8, f.multiplyScalar(6).setY(27), { color: "#dff0ff" });
          tgt.flung = true;
          sfx.kick();
          addShake(.5);
          hitstop(.05);
          spark(tgt.pos.clone().add(new THREE.Vector3(0, 3.5, 0)), 0xdff0ff, 12, 20, 1.8);
        }
      }
      break;
    }
    case "palm": {
      const tgt = a.tgt;
      if (!tgt.dead && a.t < 1.28) holdTargetInFront(tgt, 1.9);
      const times = [.3, .6, .9];
      for (let i = 0; i < 3; i++) {
        if (a.t >= times[i] && !a.hits[i]) {
          a.hits[i] = true;
          if (!tgt.dead) {
            tgt.damage(3, null, { stun: .35, color: "#ffd27a", react: "gut", reactDur: .42 });
            sfx.palm();
            hitstop(.02);
            addShake(.14);
            spark(tgt.pos.clone().add(new THREE.Vector3(0, 2.3, 0)), 0xffd27a, 5, 10, 1.2);
          }
        }
      }
      if (a.t >= 1.3 && !a.kicked) {
        a.kicked = true;
        if (!tgt.dead) {
          const f = facingVec();
          const kick = leftOf(f).multiplyScalar(30).add(f.clone().multiplyScalar(4)).setY(10);
          tgt.lockT = 0;
          tgt.damage(5, kick, { color: "#ffd27a" });
          sfx.kick();
          addShake(.45);
          hitstop(.05);
          ghostAfterimage(tgt.rig, 0xffd27a);
        }
      }
      break;
    }
    case "lim": {
      if (a.t >= .35 && !a.shattered) {
        a.shattered = true;
        startShatter();
        spark(player.pos.clone().add(new THREE.Vector3(0, 4.5, 0)), 0x9fd8ff, 8, 8, 1.2);
      }
      if (a.t >= .92 && !a.tp) {
        a.tp = true;
        const tgt = a.tgt;
        ghostAfterimage(player.rig, 0x88bbff);
        const f = camForward();
        const dst = tgt.pos.clone().addScaledVector(f, -2.8);
        dst.y = 0;
        collideWorld(dst, 1);
        p.pos.copy(dst);
        p.vel.set(0, 0, 0);
        p.facing = camYaw + Math.PI;
        p.iframes = Math.max(p.iframes, .5);
        sfx.tpDone();
        spark(p.pos.clone().add(new THREE.Vector3(0, 3, 0)), 0xbfe8ff, 14, 14, 1.6);
        ringWave(p.pos.clone().add(new THREE.Vector3(0, .3, 0)), 0x8fd0ff, 6, .4);
        ghostAfterimage(player.rig, 0xffffff);
        addShake(.2);
      }
      break;
    }

    /* ---------- NAOYA ---------- */
    case "n1": {
      /* crouch -> i-frame back-dash -> full spin roundhouse */
      if (a.t >= .12 && !a.dashed) {
        a.dashed = true;
        const f = facingVec();
        p.vel.x -= f.x * 22; p.vel.z -= f.z * 22;
        p.iframes = Math.max(p.iframes, .5);
        ghostAfterimage(p.rig, 0x9fd8ff, .35);
      }
      if (a.t >= .3 && !a.lunged) {
        a.lunged = true;
        const f = facingVec();
        p.vel.x += f.x * 34; p.vel.z += f.z * 34;
        ghostAfterimage(p.rig, 0x9fd8ff, .35);
        sfx.whoosh();
      }
      if (a.t >= .44 && !a.hit) {
        a.hit = true;
        const tgt = nearestFrontEnemy(4.8, .35);
        if (tgt) {
          const f = facingVec();
          tgt.damage(14, f.multiplyScalar(30).setY(10), { color: "#9fd8ff" });
          tgt.applyProj(35);
          sfx.kick();
          addShake(.4);
          hitstop(.05);
          ringWave(tgt.pos.clone().add(new THREE.Vector3(0, 2.6, 0)), 0x9fd8ff, 6, .4, true);
        } else {
          a.selfProj = true;
        }
        p.comboN = 0;   /* M1 count resets */
      }
      if (a.t >= a.dur - dt && a.selfProj && !a.paid) {
        a.paid = true;
        applyProjPlayer(30);   /* failed → projection applies to the user */
      }
      break;
    }
    case "n2": {
      if (a.t >= .32 && !a.thrust) {
        a.thrust = true;
        const f = facingVec();
        p.vel.x += f.x * 15; p.vel.z += f.z * 15;
      }
      if (a.t >= .4 && !a.stabbed) {
        a.stabbed = true;
        const tgt = nearestFrontEnemy(3.2, .45);
        if (tgt) {
          a.tgt = tgt;
          tgt.damage(13, facingVec().multiplyScalar(4).setY(1), { stun: .8, color: "#dfe6f2", spark: 0xff3b4e, react: "stab", reactDur: 1 });
          sfx.stab();
          hitstop(.05);
          addShake(.3);
          spark(tgt.pos.clone().add(new THREE.Vector3(0, 2.4, 0)), 0xd82a3c, 8, 12, 1.3);
          /* bleed application */
          if (tgt.bleed > 0) {
            tgt.bleed = 3;
            tgt.hemo = { ticks: 0, acc: 0 };   /* hemorrhage refresh */
            damageNumber(tgt.pos.clone().add(new THREE.Vector3(0, 6, 0)), "HEMORRHAGE", "#ff3b4e");
          } else {
            tgt.bleed = 3;
            damageNumber(tgt.pos.clone().add(new THREE.Vector3(0, 6, 0)), "BLEED x3", "#ff3b4e");
          }
          tgt.drawBars();
          /* execution finisher: target at 14 HP or less */
          if (!tgt.dead && tgt.hp <= 14) {
            a.fin = true;
            a.dur = 1.75;
          }
        } else {
          applyProjPlayer(25);
        }
      }
      /* --- finisher: blitz around, stab the neck, toss the corpse --- */
      if (a.fin && a.tgt && !a.tgt.dead) {
        const tgt = a.tgt;
        if (a.t < 1.15) { tgt.lockT = .15; tgt.vel.set(0, 0, 0); }
        const hopTimes = [.55, .68, .81, .94];
        for (let i = a.finN; i < hopTimes.length; i++) {
          if (a.t >= hopTimes[i]) {
            a.finN = i + 1;
            const ang = Math.random() * Math.PI * 2;
            ghostAfterimage(p.rig, 0x9fd8ff, .3);
            p.pos.copy(tgt.pos).add(new THREE.Vector3(Math.cos(ang) * 2, 0, Math.sin(ang) * 2));
            p.facing = Math.atan2(tgt.pos.x - p.pos.x, tgt.pos.z - p.pos.z);
            sfx.dash();
            spark(tgt.pos.clone().add(new THREE.Vector3((Math.random() - .5) * 1.6, 2 + Math.random() * 2, (Math.random() - .5) * 1.6)), 0xd82a3c, 3, 10, 1);
          }
        }
        if (a.t >= 1.18 && !a.neck) {
          a.neck = true;
          p.pos.copy(tgt.pos).add(facingVec().multiplyScalar(-1.6));
          tgt.damage(8, null, { stun: .5, color: "#ff3b4e", spark: 0xd82a3c, react: "stab", reactDur: .8 });
          sfx.stab();
          hitstop(.1);
          addShake(.6);
        }
        if (a.t >= 1.45 && !a.toss) {
          a.toss = true;
          if (!tgt.dead) {
            const f = facingVec();
            tgt.lockT = 0;
            tgt.damage(2, f.multiplyScalar(26).setY(9), { color: "#ff3b4e" });
          }
          sfx.kick();
        }
      }
      break;
    }
    case "n3": {
      /* run forward attempting the grab */
      if (!a.grabbed && a.t < .45) {
        const f = facingVec();
        p.vel.x = f.x * 16; p.vel.z = f.z * 16;
        const tgt = nearestFrontEnemy(2.6, .35);
        if (tgt) {
          a.grabbed = true;
          a.tgt = tgt;
          a.fin = tgt.hp <= 25;
          a.dur = a.fin ? 2.9 : 1.75;
          p.vel.set(0, 0, 0);
          tgt.damage(2, null, { stun: .5, color: "#ffd27a", react: "gut", reactDur: .4 });
          sfx.punch();
          addShake(.2);
        }
      }
      if (!a.grabbed && a.t >= .45 && !a.paid) {
        a.paid = true;
        a.dur = .62;
        applyProjPlayer(25);
      }
      if (a.grabbed && a.tgt && !a.tgt.dead) {
        const tgt = a.tgt;
        /* barrage */
        const barrageEnd = a.fin ? 1.9 : 1.5;
        if (a.t < barrageEnd + .2) holdTargetInFront(tgt, 2);
        if (a.t >= .5 && a.t < barrageEnd) {
          a.acc += dt;
          const rate = a.fin ? .07 : .1;
          if (a.acc > rate) {
            a.acc = 0;
            tgt.damage(1.2, null, { stun: .3, color: "#ffd27a", react: "pummel", reactDur: .25 });
            sfx.punch();
            addShake(.06);
            spark(tgt.pos.clone().add(new THREE.Vector3((Math.random() - .5) * 1.4, 2.2 + Math.random() * 1.6, (Math.random() - .5) * 1.4)), 0xffe2a8, 2, 10);
            if (a.fin && Math.random() < .3) ghostAfterimage(p.rig, 0x9fd8ff);
          }
        }
        if (!a.fin) {
          if (a.t >= 1.55 && !a.done) {
            a.done = true;
            tgt.lockT = 0;
            tgt.stunT = Math.max(tgt.stunT, 1);   /* stunned in place */
            tgt.applyProj(30);
            p.comboN = 0;                          /* set to first M1 */
          }
        } else {
          /* finisher: they retaliate — blocked — framed — kicked away */
          if (a.t >= 2.1 && !a.framed) {
            a.framed = true;
            tgt.lockT = 0;
            tgt.enterFrame("player");
            damageNumber(tgt.pos.clone().add(new THREE.Vector3(0, 6.6, 0)), "BLOCKED!", "#fff");
          }
          if (a.t >= 2.55 && !a.kicked) {
            a.kicked = true;
            if (!tgt.dead) {
              const f = facingVec();
              tgt.damage(12, f.multiplyScalar(36).setY(13), { noFrameBonus: true, color: "#ffd27a" });
              sfx.kick();
              addShake(.55);
              hitstop(.07);
            }
          }
        }
      }
      break;
    }
    case "nr": {
      /* projection dash: 24fps hops toward the aimed point */
      const HOPS = 8;
      const hopT = a.dur / HOPS;
      while (a.hop < HOPS && a.t >= (a.hop + 1) * hopT) {
        a.hop++;
        ghostAfterimage(p.rig, 0x7fb8e0, .12);
        p.pos.lerpVectors(a.from, a.dest, a.hop / HOPS);
        collideWorld(p.pos, 1);
        if (a.hop === HOPS) {
          p.vel.set(0, 0, 0);
          sfx.tpDone();
          ringWave(p.pos.clone().add(new THREE.Vector3(0, .3, 0)), 0x9fd8ff, 5, .4);
          spark(p.pos.clone().add(new THREE.Vector3(0, 3, 0)), 0xbfe8ff, 8, 10, 1.2);
          /* second teleport window, or cooldown */
          if (!a.second) {
            p.rWindow = 2.5;
          } else {
            p.rWindow = 0;
            cds.nr = CD.nr;
          }
        }
      }
      break;
    }
    case "nrf": {
      /* frame punch: blitz to the framed target and knock them out of the glass */
      const tgt = a.tgt;
      if (a.t >= .18 && !a.hopped) {
        a.hopped = true;
        ghostAfterimage(p.rig, 0x9fd8ff);
        const f = camForward();
        p.pos.copy(tgt.pos).addScaledVector(f, -2.2);
        p.pos.y = 0;
        collideWorld(p.pos, 1);
        p.facing = camYaw + Math.PI;
        sfx.dash();
      }
      if (a.t >= .32 && !a.punched) {
        a.punched = true;
        if (!tgt.dead && tgt.frameT > 0) {
          const f = facingVec();
          tgt.damage(8, f.multiplyScalar(30).setY(11), { color: "#9fd8ff" });   /* triple applies via frame break */
          tgt.applyProj(27);   /* refills their meter by 27% */
          sfx.punch();
          addShake(.45);
          hitstop(.07);
        }
      }
      break;
    }
  }
}

/* ============================================================
   ACTION POSES
   ============================================================ */
function poseAction(r, a) {
  const p = player;
  p.visYaw = 0;
  switch (a.type) {
    case "red": {
      if (a.t < .5) {
        const k = ease(clamp01(a.t / .35));
        r.shoulderR.rotation.x = -2.25 * k;
        r.elbowR.rotation.x = -.2;
        r.shoulderL.rotation.x = -.5; r.elbowL.rotation.x = -1.1;
        r.spine.rotation.x = .1 * k;
        r.spine.rotation.y = -.3 * k;
        r.neck.rotation.x = -.12 * k;
      } else {
        const k = ease(clamp01((a.t - .5) / .18));
        r.shoulderR.rotation.x = lerp(-2.25, -1.45, k);
        r.elbowR.rotation.x = -.06;
        r.shoulderL.rotation.x = -.3; r.elbowL.rotation.x = -.8;
        r.spine.rotation.x = lerp(.1, -.12, k);
        r.spine.rotation.y = lerp(-.3, -.45, k);
      }
      break;
    }
    case "rapid": {
      if (a.t < .3) {
        const k = a.t / .3;
        p.visYaw = k * Math.PI * 2;
        r.hipR.rotation.x = -1.5 * Math.sin(k * Math.PI);
        r.kneeR.rotation.x = .12;
        r.hipL.rotation.x = .25; r.kneeL.rotation.x = .4;
        r.shoulderL.rotation.z = -.9; r.shoulderR.rotation.z = .9;
        r.spine.rotation.x = .12;
      } else if (a.t < 1.45 && a.locked) {
        const f = Math.sin(a.t * 46);
        r.shoulderR.rotation.x = -1.35 + f * .55;
        r.shoulderL.rotation.x = -1.35 - f * .55;
        r.elbowR.rotation.x = -.22; r.elbowL.rotation.x = -.22;
        r.spine.rotation.x = -.16;
        r.hipL.rotation.x = -.24; r.hipR.rotation.x = .26;
        r.kneeL.rotation.x = .3; r.kneeR.rotation.x = .34;
        if (Math.random() < .3) ghostAfterimage(player.rig, 0x5588ff);
      } else if (a.locked) {
        const k = ease(clamp01((a.t - 1.45) / .18));
        r.shoulderR.rotation.x = -1.85;
        r.elbowR.rotation.x = -.04;
        r.shoulderL.rotation.x = .35;
        r.spine.rotation.y = -.55 * k;
        r.spine.rotation.x = -.2;
        r.hipL.rotation.x = -.35; r.hipR.rotation.x = .4; r.kneeR.rotation.x = .5;
      }
      break;
    }
    case "tf": {
      if (a.t < .18) {
        const k = ease(a.t / .18);
        r.hipR.rotation.x = lerp(.45, -1.9, k);
        r.kneeR.rotation.x = lerp(.9, .08, k);
        r.spine.rotation.x = .3 * k;
        r.shoulderL.rotation.x = -.85; r.shoulderR.rotation.x = .5;
        r.ankleR.rotation.x = .3;
      } else if (a.t < .58) {
        const k = clamp01((a.t - .18) / .4);
        r.hipR.rotation.x = lerp(-1.9, -1, k);
        r.kneeR.rotation.x = .15;
        r.spine.rotation.x = lerp(.3, .12, k);
        r.shoulderL.rotation.x = -.6; r.shoulderR.rotation.x = .3;
      } else {
        const k = ease(clamp01((a.t - .58) / .18));
        r.hipL.rotation.x = lerp(.3, -2.1, k);
        r.kneeL.rotation.x = .1;
        r.hipR.rotation.x = .35; r.kneeR.rotation.x = .6;
        r.spine.rotation.x = .38;
        r.shoulderL.rotation.x = .4; r.shoulderR.rotation.x = -.7;
      }
      break;
    }
    case "palm": {
      r.shoulderL.rotation.x = -1.45; r.elbowL.rotation.x = -.12;
      const times = [.3, .6, .9];
      let strike = 0;
      for (const st of times) {
        const d = a.t - st;
        if (d > -.08 && d < .1) strike = 1 - Math.abs(d) * 8;
      }
      r.shoulderR.rotation.x = -.55 - strike * 1.1;
      r.elbowR.rotation.x = -.25 + strike * .1;
      r.spine.rotation.y = -.15 - strike * .2;
      r.spine.rotation.x = -.08;
      if (a.t >= .95 && a.t < 1.28) {
        const k = (a.t - .95) / .33;
        p.visYaw = ease(k) * Math.PI * 2;
        r.shoulderL.rotation.x = -.4; r.shoulderR.rotation.x = -.4;
        r.shoulderL.rotation.z = -.7; r.shoulderR.rotation.z = .7;
      } else if (a.t >= 1.28 && a.t < 1.5) {
        const k = ease(clamp01((a.t - 1.28) / .15));
        r.hipR.rotation.x = -1.35 * k;
        r.kneeR.rotation.x = .1;
        r.spine.rotation.y = .6 * k;
        r.spine.rotation.x = .15;
        r.shoulderL.rotation.x = .3; r.shoulderR.rotation.x = .3;
      }
      break;
    }
    case "lim": {
      const k = ease(clamp01(a.t / .3));
      const down = a.t > .95 ? ease(clamp01((a.t - .95) / .2)) : 0;
      r.shoulderR.rotation.x = -2.95 * k * (1 - down);
      r.elbowR.rotation.x = -.08;
      r.shoulderL.rotation.x = .1;
      r.neck.rotation.x = -.28 * k * (1 - down);
      r.spine.rotation.x = .06;
      if (a.shattered && !a.tp && Math.random() < .25)
        spark(handWorld(player.rig.handR), 0x9fd8ff, 1, 3, .7);
      break;
    }

    /* ---------- NAOYA ---------- */
    case "n1": {
      /* crouch anticipation -> back-dash slide -> spin roundhouse -> follow-through */
      if (a.t < .12) {
        const k = ease(a.t / .12);
        r.spine.rotation.x = .38 * k;
        r.neck.rotation.x = .2 * k;
        r.kneeL.rotation.x = .85 * k; r.kneeR.rotation.x = .85 * k;
        r.hipL.rotation.x = -.42 * k; r.hipR.rotation.x = -.42 * k;
        r.shoulderL.rotation.x = .7 * k; r.shoulderR.rotation.x = .7 * k;
        r.hips.position.y = r.hipsBaseY - .32 * k;
      } else if (a.t < .3) {
        const k = ease((a.t - .12) / .18);
        r.spine.rotation.x = lerp(.38, -.52, k);
        r.neck.rotation.x = lerp(.2, .38, k);
        r.shoulderL.rotation.x = lerp(.7, -1.3, k);
        r.shoulderR.rotation.x = lerp(.7, -1.3, k);
        r.shoulderL.rotation.z = -.35 * k; r.shoulderR.rotation.z = .35 * k;
        r.elbowL.rotation.x = -.3; r.elbowR.rotation.x = -.3;
        r.hipL.rotation.x = lerp(-.42, -1, k); r.kneeL.rotation.x = lerp(.85, .2, k);
        r.hipR.rotation.x = lerp(-.42, .32, k); r.kneeR.rotation.x = lerp(.85, 1.2, k);
        r.hips.position.y = r.hipsBaseY - .18;
      } else if (a.t < .56) {
        const k = ease((a.t - .3) / .26);
        p.visYaw = k * Math.PI * 2;
        const kick = Math.sin(Math.min(1, k * 1.35) * Math.PI);
        r.hipR.rotation.x = -1.85 * kick;
        r.kneeR.rotation.x = 1.4 * (1 - kick) + .08;
        r.ankleR.rotation.x = .35 * kick;
        r.hipL.rotation.x = .3; r.kneeL.rotation.x = .55;
        r.spine.rotation.x = .1;
        r.spine.rotation.z = -.32 * kick;
        r.neck.rotation.z = .15 * kick;
        r.shoulderL.rotation.z = -1.25 * kick; r.shoulderR.rotation.z = 1.25 * kick;
        r.shoulderL.rotation.x = -.3; r.shoulderR.rotation.x = -.3;
        r.hips.position.y = r.hipsBaseY - .12;
      } else {
        const k = ease(clamp01((a.t - .56) / .24));
        p.visYaw = Math.PI * 2;
        r.hipR.rotation.x = lerp(-1.85, .2, k);
        r.kneeR.rotation.x = lerp(.08, .5, k);
        r.spine.rotation.z = lerp(-.32, 0, k);
        r.spine.rotation.x = lerp(.1, .22, k);
        r.kneeL.rotation.x = .55;
        r.shoulderL.rotation.z = lerp(-1.25, -.15, k);
        r.shoulderR.rotation.z = lerp(1.25, .15, k);
        r.hips.position.y = r.hipsBaseY - .18 * (1 - k);
      }
      break;
    }
    case "n2": {
      /* blade flourish -> deep stab lunge -> withdraw (or finisher blitz) */
      if (a.t < .3) {
        const k = ease(a.t / .3);
        r.shoulderR.rotation.x = -1.25 * k;
        r.shoulderR.rotation.z = .45 * k;
        r.elbowR.rotation.x = -1.55 * k;
        r.shoulderL.rotation.x = -.75 * k;
        r.elbowL.rotation.x = -.9 * k;
        r.spine.rotation.y = .4 * k;
        r.spine.rotation.x = .08 * k;
        r.neck.rotation.y = -.3 * k;
        r.hipL.rotation.x = -.15 * k; r.kneeR.rotation.x = .35 * k;
        r.hips.position.y = r.hipsBaseY - .1 * k;
        if (r.tanto) r.tanto.rotation.x = ease(k) * Math.PI * 6;
      } else if (a.t < .46) {
        const k = ease(clamp01((a.t - .3) / .16));
        r.shoulderR.rotation.x = lerp(-1.25, -1.62, k);
        r.shoulderR.rotation.z = lerp(.45, .05, k);
        r.elbowR.rotation.x = lerp(-1.55, -.02, k);
        r.shoulderL.rotation.x = lerp(-.75, .65, k);
        r.elbowL.rotation.x = lerp(-.9, -1.35, k);
        r.spine.rotation.y = lerp(.4, -.55, k);
        r.spine.rotation.x = lerp(.08, -.18, k);
        r.neck.rotation.y = lerp(-.3, .1, k);
        r.hipL.rotation.x = -.55 * k; r.kneeL.rotation.x = .35 * k;
        r.hipR.rotation.x = .4 * k; r.kneeR.rotation.x = lerp(.35, .5, k);
        r.hips.position.y = r.hipsBaseY - .22 * k;
        if (r.tanto) r.tanto.rotation.x = 0;
      } else if (!a.fin) {
        const k = ease(clamp01((a.t - .46) / .32));
        const inv = 1 - k;
        r.shoulderR.rotation.x = -1.62 * inv - .2 * k;
        r.elbowR.rotation.x = -.02 - .6 * k;
        r.shoulderL.rotation.x = .65 * inv;
        r.elbowL.rotation.x = -1.35 * inv - .2 * k;
        r.spine.rotation.y = -.55 * inv;
        r.spine.rotation.x = -.18 * inv;
        r.hipL.rotation.x = -.55 * inv; r.hipR.rotation.x = .4 * inv;
        r.kneeR.rotation.x = .5 * inv + .06;
        r.hips.position.y = r.hipsBaseY - .22 * inv;
      } else if (a.t < 1.15) {
        /* finisher: blitzing slashes around the target, alternating sides */
        const sl = Math.floor(a.t * 8) % 2 ? 1 : -1;
        const jit = Math.sin(a.t * 34);
        r.spine.rotation.y = .6 * sl;
        r.spine.rotation.x = -.15;
        r.neck.rotation.y = -.3 * sl;
        r.shoulderR.rotation.x = -1.3 + jit * .3;
        r.shoulderR.rotation.z = .3 * sl;
        r.elbowR.rotation.x = -.15;
        r.shoulderL.rotation.x = -.6 * sl;
        r.elbowL.rotation.x = -.8;
        r.kneeL.rotation.x = .5; r.kneeR.rotation.x = .5;
        r.hipL.rotation.x = -.3; r.hipR.rotation.x = .2;
        r.hips.position.y = r.hipsBaseY - .26;
      } else if (a.t < 1.45) {
        /* rising neck stab, up on the toes */
        const k = ease(clamp01((a.t - 1.15) / .14));
        r.shoulderR.rotation.x = lerp(-1.3, -2.05, k);
        r.elbowR.rotation.x = -.04;
        r.shoulderL.rotation.x = lerp(-.6, .5, k);
        r.spine.rotation.y = -.5 * k;
        r.spine.rotation.x = lerp(-.15, -.3, k);
        r.neck.rotation.x = -.25 * k;
        r.ankleL.rotation.x = -.3 * k; r.ankleR.rotation.x = -.3 * k;
        r.hips.position.y = r.hipsBaseY + .08 * k;
      } else {
        /* wrenching the blade out and tossing the body */
        const k = ease(clamp01((a.t - 1.45) / .2));
        p.visYaw = k * Math.PI * .7;
        r.shoulderR.rotation.x = lerp(-2.05, -.35, k);
        r.shoulderR.rotation.z = .85 * k;
        r.shoulderL.rotation.x = lerp(.5, -.9, k);
        r.spine.rotation.y = lerp(-.5, .5, k);
        r.spine.rotation.x = .12 * k;
        r.kneeL.rotation.x = .3; r.kneeR.rotation.x = .4;
      }
      break;
    }
    case "n3": {
      if (!a.grabbed) {
        /* weaving sprint with a grasping reach */
        const s = Math.sin(a.t * 26);
        p.visYaw = Math.sin(a.t * 16) * .12;
        r.spine.rotation.x = -.45;
        r.spine.rotation.y = Math.sin(a.t * 20) * .15;
        r.neck.rotation.x = .3;
        r.shoulderL.rotation.x = -1.5 + Math.sin(a.t * 10) * .1;
        r.elbowL.rotation.x = -.1;
        r.shoulderR.rotation.x = .8;
        r.elbowR.rotation.x = -.4;
        r.hipL.rotation.x = -s * 1.05; r.hipR.rotation.x = s * 1.05;
        r.kneeL.rotation.x = .45 + Math.max(0, Math.cos(a.t * 26)) * .85;
        r.kneeR.rotation.x = .45 + Math.max(0, -Math.cos(a.t * 26)) * .85;
        r.hips.position.y = r.hipsBaseY - .18;
      } else if (!a.fin) {
        /* alternating straights driven from the hips, with sudden knee strikes */
        const alt = Math.sin(a.t * 22);
        const kneeStrike = Math.sin(a.t * 2.9 - 1) > .93;
        r.spine.rotation.x = -.22;
        r.spine.rotation.y = alt * .38;
        r.neck.rotation.x = .1;
        r.shoulderR.rotation.x = -1.15 - Math.max(0, alt) * .75;
        r.shoulderL.rotation.x = -1.15 - Math.max(0, -alt) * .75;
        r.elbowR.rotation.x = -.18 - Math.max(0, -alt) * .95;
        r.elbowL.rotation.x = -.18 - Math.max(0, alt) * .95;
        if (kneeStrike) {
          r.hipR.rotation.x = -1.35; r.kneeR.rotation.x = 1.25;
          r.spine.rotation.x = -.32;
        } else {
          r.hipL.rotation.x = -.25; r.hipR.rotation.x = .28;
          r.kneeL.rotation.x = .35; r.kneeR.rotation.x = .38;
        }
        r.hips.position.y = r.hipsBaseY - .12 + Math.sin(a.t * 44) * .02;
      } else {
        if (a.t < 1.9) {
          /* overwhelming one-arm blur while the other caresses his hair */
          const f = Math.sin(a.t * 54);
          r.shoulderR.rotation.x = -1.35 + f * .65;
          r.elbowR.rotation.x = -.12;
          r.spine.rotation.y = -.15 + f * .08;
          r.spine.rotation.x = -.12;
          r.shoulderL.rotation.x = -2.55;
          r.shoulderL.rotation.z = -.25;
          r.elbowL.rotation.x = -1.42 + Math.sin(a.t * 2.2) * .12;
          r.neck.rotation.z = -.14;
          r.neck.rotation.x = -.16;
          r.hipL.rotation.z = -.08;
          r.kneeR.rotation.x = .3;
          r.hips.position.x = .1;
        } else if (a.t < 2.1) {
          /* snapping into a cross-arm block */
          const k = ease(clamp01((a.t - 1.9) / .08));
          r.shoulderL.rotation.x = -1.05 * k; r.shoulderR.rotation.x = -1.05 * k;
          r.elbowL.rotation.x = -1.35 * k;    r.elbowR.rotation.x = -1.35 * k;
          r.spine.rotation.x = .12 * k;
          r.neck.rotation.x = .2 * k;
          r.kneeL.rotation.x = .3; r.kneeR.rotation.x = .3;
          r.hips.position.y = r.hipsBaseY - .1 * k;
        } else if (a.t < 2.55) {
          /* dismissive flick, chin up, half turned away as the frame sets */
          const k = ease(clamp01((a.t - 2.1) / .2));
          p.visYaw = -.6 * k;
          r.shoulderR.rotation.x = -.3;
          r.shoulderR.rotation.z = .85 * k;
          r.elbowR.rotation.x = -.25 + Math.sin((a.t - 2.1) * 18) * .2 * (1 - k);
          r.shoulderL.rotation.x = .25;
          r.neck.rotation.z = .12;
          r.neck.rotation.x = -.18;
          r.spine.rotation.y = .35 * k;
        } else {
          /* wheeling heavy kick */
          const k = ease(clamp01((a.t - 2.55) / .14));
          p.visYaw = lerp(-.6, 0, k);
          r.hipR.rotation.x = -1.95 * k;
          r.kneeR.rotation.x = .08;
          r.ankleR.rotation.x = .3 * k;
          r.spine.rotation.x = .35 * k;
          r.spine.rotation.z = -.25 * k;
          r.shoulderL.rotation.x = .5; r.shoulderR.rotation.x = -.85;
          r.shoulderL.rotation.z = -.8 * k; r.shoulderR.rotation.z = .5;
          r.kneeL.rotation.x = .4;
          r.hips.position.y = r.hipsBaseY - .15 * k;
        }
      }
      break;
    }
    case "nr": {
      /* 24fps blitz: pose changes with every projection hop */
      const mode = a.hop % 3;
      r.spine.rotation.x = -.5;
      r.neck.rotation.x = .32;
      if (mode === 0) {
        r.shoulderL.rotation.x = .95; r.shoulderR.rotation.x = .95;
        r.shoulderL.rotation.z = -.35; r.shoulderR.rotation.z = .35;
        r.hipL.rotation.x = -.9; r.kneeL.rotation.x = 1;
        r.hipR.rotation.x = .55; r.kneeR.rotation.x = .25;
      } else if (mode === 1) {
        /* low slide */
        r.spine.rotation.x = -.3;
        r.hips.position.y = r.hipsBaseY - .5;
        r.hipL.rotation.x = -1.3; r.kneeL.rotation.x = .2;
        r.hipR.rotation.x = .8; r.kneeR.rotation.x = 1.5;
        r.shoulderL.rotation.x = -.6; r.shoulderR.rotation.x = .8;
      } else {
        /* upright glide, hand raised in the technique sign */
        r.shoulderR.rotation.x = -2.5; r.elbowR.rotation.x = -.1;
        r.shoulderL.rotation.x = .8;
        r.hipL.rotation.x = -.5; r.kneeL.rotation.x = .7;
        r.hipR.rotation.x = .35; r.kneeR.rotation.x = .4;
      }
      break;
    }
    case "nrf": {
      /* frame break: cock the fist behind, then a full-body straight */
      if (a.t < .18) {
        const k = ease(a.t / .18);
        r.spine.rotation.y = .55 * k;
        r.shoulderR.rotation.x = .75 * k;
        r.shoulderR.rotation.z = .35 * k;
        r.elbowR.rotation.x = -1.1 * k;
        r.shoulderL.rotation.x = -.8 * k;
        r.kneeL.rotation.x = .3; r.kneeR.rotation.x = .4;
        r.hips.position.y = r.hipsBaseY - .12 * k;
      } else {
        const k = ease(clamp01((a.t - .18) / .16));
        r.spine.rotation.y = lerp(.55, -.65, k);
        r.spine.rotation.x = -.15 * k;
        r.shoulderR.rotation.x = lerp(.75, -1.55, k);
        r.shoulderR.rotation.z = lerp(.35, .05, k);
        r.elbowR.rotation.x = lerp(-1.1, -.02, k);
        r.shoulderL.rotation.x = lerp(-.8, .5, k);
        r.elbowL.rotation.x = -.9;
        r.hipL.rotation.x = -.5 * k; r.kneeL.rotation.x = .3;
        r.hipR.rotation.x = .45 * k; r.kneeR.rotation.x = .55 * k;
        r.hips.position.y = r.hipsBaseY - .18 * k;
      }
      break;
    }
  }
}

/* ---------------- input ---------------- */
let keys = {};
let locked = false, started = false;
const menu = document.getElementById("menu");
const menuFight = document.getElementById("menuFight");
const menuSub = menu.querySelector("h2");
let sprinting = false, lastForwardTap = -Infinity;
const shiftLock = { enabled: false, pending: false, blocked: false, dragging: false, serial: 0 };
function gameInputActive() {
  const lobby = document.getElementById('jjLobby');
  return started && menu.style.display === 'none' && (!lobby || lobby.style.display !== 'flex');
}
function typingInUI(e) {
  return e.target && e.target.closest && e.target.closest('input, textarea, select, [contenteditable="true"]');
}
function clearMovement() {
  for (const key in keys) keys[key] = false;
  sprinting = false; lastForwardTap = -Infinity;
  if (window.JJFIGHT) JJFIGHT.clearInput();
}
function refreshMouseUI() {
  const active = gameInputActive();
  document.getElementById('jjMouseControls').style.display = active ? 'block' : 'none';
  const button = document.getElementById('jjShiftLock');
  button.setAttribute('aria-pressed', String(locked && shiftLock.enabled));
  button.textContent = shiftLock.pending ? 'SHIFT LOCK: CONNECTING…' : locked && shiftLock.enabled ? 'SHIFT LOCK: ON' : 'SHIFT LOCK: OFF';
  const hint = shiftLock.blocked ? 'Mouse lock unavailable here. Hold right mouse to look.' :
    locked ? 'Shift / Esc: free cursor · W W: sprint' : 'Shift: lock · Hold right mouse: look · W W: sprint';
  const hintEl = document.getElementById('jjMouseHint');
  if (hintEl.textContent !== hint) hintEl.textContent = hint;
  document.getElementById('crosshair').style.display = active && locked ? 'block' : 'none';
  document.body.classList.toggle('jjLocked', active && (locked || shiftLock.dragging));
  window.dispatchEvent(new Event('jjshiftchange'));
}
function setShiftLock(on) {
  const serial = ++shiftLock.serial;
  shiftLock.enabled = !!on && gameInputActive();
  shiftLock.pending = shiftLock.enabled && !locked;
  shiftLock.dragging = false;
  if (!shiftLock.enabled) {
    if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
    refreshMouseUI();
    return;
  }
  shiftLock.blocked = false;
  refreshMouseUI();
  if (locked) return;
  const fail = () => {
    if (serial !== shiftLock.serial || !shiftLock.pending) return;
    shiftLock.enabled = false; shiftLock.pending = false; shiftLock.blocked = true;
    refreshMouseUI();
  };
  try {
    if (!renderer.domElement.requestPointerLock) { fail(); return; }
    const request = renderer.domElement.requestPointerLock();
    if (request && request.catch) request.catch(fail);
  } catch (_) { fail(); }
}
function toggleShiftLock() { setShiftLock(!shiftLock.enabled); }
window.JJSHIFT = {
  toggle: toggleShiftLock, unlock() { setShiftLock(false); }, refresh: refreshMouseUI,
  get active() { return locked && shiftLock.enabled; },
  get blocked() { return shiftLock.blocked; },
  get dragging() { return shiftLock.dragging; }
};
function openGameMenu() {
  clearMovement(); setShiftLock(false); setMenuMode(true);
  menu.style.display = 'flex'; refreshMouseUI();
}
document.getElementById('jjShiftLock').addEventListener('click', e => {
  e.stopPropagation(); toggleShiftLock(); e.currentTarget.blur();
});
document.getElementById('jjPause').addEventListener('click', openGameMenu);
document.addEventListener('pointerlockchange', () => {
  locked = document.pointerLockElement === renderer.domElement;
  if (locked && !shiftLock.enabled) { document.exitPointerLock(); return; }
  if (locked) { shiftLock.pending = false; shiftLock.blocked = false; }
  else if (!shiftLock.pending) shiftLock.enabled = false;
  shiftLock.dragging = false;
  refreshMouseUI();
});
document.addEventListener('pointerlockerror', () => {
  if (!shiftLock.pending) return;
  shiftLock.pending = false; shiftLock.enabled = false; shiftLock.blocked = true;
  refreshMouseUI();
});
addEventListener('blur', () => { clearMovement(); setShiftLock(false); });
document.addEventListener('visibilitychange', () => {
  if (document.hidden) { clearMovement(); setShiftLock(false); }
});
addEventListener('keydown', e => {
  if (window.JJOPENING && JJOPENING.input(e)) return;
  if (typingInUI(e)) return;
  if (e.code === 'Escape' && started && !e.repeat) {
    if (shiftLock.enabled || locked) setShiftLock(false);
    else if (gameInputActive()) openGameMenu();
    else if (menu.style.display !== 'none') enterArenaLocal(e);
    e.preventDefault(); e.stopImmediatePropagation();
    return;
  }
  if (!gameInputActive() || e.ctrlKey || e.metaKey || e.altKey) return;
  if (window.JJDOMAINCLASH && JJDOMAINCLASH.input(e)) return;
  if (window.JJFIGHT && JJFIGHT.input(e)) return;
  if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
    if (!e.repeat) toggleShiftLock();
    e.preventDefault(); e.stopImmediatePropagation();
  }
}, true);

function setMenuMode(pause) {
  menu.classList.toggle("is-pause", !!pause);
  if (menuSub) menuSub.textContent = pause ? "PAUSED" : "FIVE SORCERERS · ONE CITY";
  if (menuFight) menuFight.textContent = pause ? "RESUME" : "ENTER THE ARENA";
}
function enterArenaLocal(e) {
  if (e) { e.preventDefault(); e.stopPropagation(); }
  started = true;
  menu.style.display = "none";
  audio();
  clearMovement();
  refreshMouseUI();
}

addEventListener("keydown", e => {
  if (typingInUI(e) || e.ctrlKey || e.metaKey || e.altKey) return;
  if (!started && (e.code === "Enter" || e.code === "Space")) {
    const lobby = document.getElementById("jjLobby");
    if (lobby && lobby.style.display === "flex") return;
    if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA")) return;
    enterArenaLocal(e);
    return;
  }
  if (!gameInputActive()) return;
  keys[e.code] = true;
  if (e.code === 'KeyW' && !e.repeat) {
    const now = performance.now();
    if (now - lastForwardTap < 300) sprinting = true;
    lastForwardTap = now;
  }
  if (player.char === "gojo") {
    if (e.code === "Digit1") castRed();
    if (e.code === "Digit2") castRapid();
    if (e.code === "Digit3") castTwofold();
    if (e.code === "Digit4") castPalm();
    if (e.code === "KeyR") castLimitless();
  } else {
    if (e.code === "Digit1") castN1();
    if (e.code === "Digit2") castN2();
    if (e.code === "Digit3") castN3();
    if (e.code === "KeyR") castNaoyaR();
  }
  if (e.code === "KeyQ") doDash();
  if (e.code === "KeyC" && !e.repeat) switchChar(player.char === "gojo" ? "naoya" : "gojo");
});
addEventListener("keyup", e => {
  keys[e.code] = false;
  if (e.code === 'KeyW') sprinting = false;
});

if (menuFight) menuFight.addEventListener("click", enterArenaLocal);
menu.addEventListener("click", (e) => {
  if (!started) return;
  if (e.target.closest("button, .roster-card, input, a, .controls")) return;
  enterArenaLocal(e);
});
addEventListener("mousemove", e => {
  if (!gameInputActive() || (!locked && !shiftLock.dragging)) return;
  if (shiftLock.dragging && !(e.buttons & 2)) {
    shiftLock.dragging = false; refreshMouseUI(); return;
  }
  camYaw -= e.movementX * .0026;
  camPitch = Math.max(-.5, Math.min(1.1, camPitch + e.movementY * .0022));
});
addEventListener("mousedown", e => {
  if (!gameInputActive() || (!locked && e.target !== renderer.domElement)) return;
  if (!locked && e.button === 2) {
    shiftLock.dragging = true; refreshMouseUI(); e.preventDefault();
  }
  if (e.button === 0) punch();
});
addEventListener('mouseup', e => {
  if (e.button === 2 && shiftLock.dragging) { shiftLock.dragging = false; refreshMouseUI(); }
});
renderer.domElement.addEventListener('contextmenu', e => { if (gameInputActive()) e.preventDefault(); });

/* ---------------- player update ---------------- */
const WALK_SPEED = 7.2, RUN_SPEED = 13.5;
function worldFloor(pos, limit) {
  return window.JJMAP ? JJMAP.floor(pos, limit) : 0;
}
function resolveActorWorld(actor, previousY, radius) {
  const jjs = window.JJMAP && JJMAP.id === 'jjs';
  if (jjs && actor.onGround) {
    // Sweep at torso height before resolving overlap, so a dash cannot pass
    // through a thin wall between two animation frames.
    const last = actor.__jjsLast;
    if (last && Math.hypot(actor.pos.x-last.x,actor.pos.z-last.z)>radius) {
      const from=last.clone().add(new THREE.Vector3(0,2.5,0)),to=actor.pos.clone().add(new THREE.Vector3(0,2.5,0));
      const fraction=JJJJS.ray(from,to,radius*.8);
      if(fraction<.999){actor.pos.x=lerp(last.x,actor.pos.x,fraction);actor.pos.z=lerp(last.z,actor.pos.z,fraction);}
    }
  }
  collideWorld(actor.pos, radius);
  const limit=Math.max(previousY,actor.pos.y)+(jjs&&actor.onGround?JJJJS.STEP:.025);
  const floor=worldFloor(actor.pos,limit);
  let landed=actor.vel.y<=0&&actor.pos.y<=floor+.025;
  if(landed){actor.pos.y=floor;actor.vel.y=0;actor.onGround=true;}
  else actor.onGround=false;
  if(jjs){
    if(actor.vel.y>0){const ceiling=JJMAP.ceiling(actor.pos,previousY+JJJJS.HEIGHT-.025);if(actor.pos.y+JJJJS.HEIGHT>ceiling){actor.pos.y=ceiling-JJJJS.HEIGHT;actor.vel.y=0;}}
    if(actor.pos.y<JJMAP.killY){const sp=JJMAP.spawn();actor.pos.set(sp.x,sp.y,sp.z);actor.vel.set(0,0,0);actor.onGround=true;landed=true;}
    actor.__jjsLast=actor.pos.clone();
  }else actor.__jjsLast=null;
  return landed;
}
function updatePlayer(dt) {
  const p = player;
  const r = p.rig;
  if (p.dead) {
    p.deathT -= dt;
    r.body.rotation.x = Math.min(r.body.rotation.x + dt * 4, Math.PI / 2);
    if (p.deathT <= 0) {
      p.dead = false; p.hp = p.maxHp;
      const sp=window.JJMAP&&JJMAP.id==='jjs'?JJMAP.spawn():{x:0,y:0,z:20};
      p.pos.set(sp.x, sp.y || 0, sp.z); p.vel.set(0, 0, 0);p.__jjsLast=null;
      r.body.rotation.x = 0;
      p.iframes = 2;
      p.proj = 0;
    }
    r.root.position.copy(p.pos);
    return;
  }
  /* frozen in own glass frame */
  if (p.worldRag && p.rag) { p.iframes = Math.max(0, p.iframes - dt); return; }
  if (p.frameT > 0) {
    p.frameT -= dt;
    if (p.frameT <= 0) unframePlayer(false);
    return;
  }
  p.iframes = Math.max(0, p.iframes - dt);
  p.animT += dt;
  if (p.comboReset > 0) { p.comboReset -= dt; if (p.comboReset <= 0) p.comboN = 0; }
  for (const k in cds) cds[k] = Math.max(0, cds[k] - dt);
  /* dash charges */
  const dashMax = p.char === "naoya" ? 2 : 1;
  p.dashCh = Math.min(dashMax, p.dashCh + dt / 2.2);
  /* naoya double-teleport window */
  if (p.rWindow > 0) {
    p.rWindow -= dt;
    if (p.rWindow <= 0 && cds.nr <= 0) cds.nr = CD.nr;
  }
  /* projection meter passive drain */
  if (p.proj > 0) p.proj = Math.max(0, p.proj - dt * 2);

  if (window.JJFIGHT) JJFIGHT.beforeStep(dt);
  if (window.JJMOVE) JJMOVE.beforeStep(dt);
  if (window.JJIWORLD) JJIWORLD.beforeStep(dt);

  if (p.action) {
    const a = p.action;
    a.t += dt;
    stepAction(a, dt);
    if (p.action === a && a.t >= a.dur) {
      p.action = null;
      p.visYaw = 0;
      if (r.tanto) r.tanto.visible = false;
    }
  }
  const inAction = !!p.action;

  // Traversal advances a swept path against the same world collision. The
  // combat timers and pose layers above/below continue to run normally.
  if ((!window.JJMOVE || !JJMOVE.driving()) && (!window.JJFIGHT || !JJFIGHT.driving()) && (!window.JJIWORLD || !JJIWORLD.driving())) {
  const fwd = camForward();
  const rightv = new THREE.Vector3(-fwd.z, 0, fwd.x);
  const mv = new THREE.Vector3();
  const combatMotion = window.JJFIGHT ? JJFIGHT.motion() : null;
  if ((!inAction || combatMotion?.attackWalk) && !combatMotion?.stunned) {
    if (keys["KeyW"]) mv.add(fwd);
    if (keys["KeyS"]) mv.sub(fwd);
    if (keys["KeyD"]) mv.add(rightv);
    if (keys["KeyA"]) mv.sub(rightv);
  }
  const moving = mv.lengthSq() > 0;
  if (moving) mv.normalize();
  const running = moving && sprinting;
  const speed = combatMotion?.speed ?? (running ? RUN_SPEED : WALK_SPEED);

  const targetV = moving ? mv.multiplyScalar(speed) : new THREE.Vector3();
  const drag = inAction ? 3 : 10;
  p.vel.x += (targetV.x - p.vel.x) * Math.min(1, dt * drag);
  p.vel.z += (targetV.z - p.vel.z) * Math.min(1, dt * drag);

  if (keys["Space"] && p.onGround && !inAction && !combatMotion?.noJump) {
    p.vel.y = 15;
    p.onGround = false;
    sfx.whoosh();
  }
  const previousY = p.pos.y;
  p.vel.y -= 34 * dt;
  p.pos.addScaledVector(p.vel, dt);
  resolveActorWorld(p, previousY, 1);

  if (running && p.onGround && Math.hypot(p.vel.x, p.vel.z) > RUN_SPEED * .7) {
    p.ghostAcc += dt;
    const gap = p.char === "naoya" ? .2 : .24;
    if (p.ghostAcc > gap) { p.ghostAcc = 0; ghostAfterimage(r, p.char === "naoya" ? 0x6a9cc0 : 0x2a4dcc, .16); }
  }

  let desired = p.facing;
  if (locked || inAction || p.attackT > 0) desired = camYaw + Math.PI;
  else if (moving) desired = Math.atan2(targetV.x, targetV.z);
  let dy = desired - p.facing;
  while (dy > Math.PI) dy -= Math.PI * 2;
  while (dy < -Math.PI) dy += Math.PI * 2;
  p.facing += dy * Math.min(1, dt * 14);
  }

  /* ------- animation (24 FPS rule applies to Naoya's visuals) ------- */
  const sp = Math.hypot(p.vel.x, p.vel.z);
  if (sp > .4) p.gait += dt * (4.2 + sp * .92);
  p.vis24 += dt;
  const gate = p.char === "naoya" ? 1 / 24 : 0;
  if (gate === 0 || p.vis24 >= gate) {
    p.vis24 = 0;
    const moveAmt = clamp01(sp / 2.2);
    const runAmt = clamp01((sp - WALK_SPEED * .92) / (RUN_SPEED - WALK_SPEED));
    resetPose(r);
    applyLocomotion(r, p.animT, p.gait, moveAmt, runAmt, p.onGround, p.vel.y);
    if (p.char === "naoya" && !inAction && p.attackT <= 0) applyNaoyaFlair(r, p.animT, moveAmt, runAmt, p.onGround);

    if (p.attackT > 0) {
      const L = p.attackArm === 0;
      const sh = L ? r.shoulderL : r.shoulderR;
      const el = L ? r.elbowL : r.elbowR;
      const osh = L ? r.shoulderR : r.shoulderL;
      const oel = L ? r.elbowR : r.elbowL;
      sh.rotation.x = -1.75; el.rotation.x = -.08;
      osh.rotation.x = -.7; oel.rotation.x = -1.35;
      r.spine.rotation.y = L ? .38 : -.38;
      r.spine.rotation.x = -.1;
    }
    if (p.action) poseAction(r, p.action);

    r.root.rotation.y = p.facing + p.visYaw;
    r.root.position.copy(p.pos);
  }
  if (p.attackT > 0) p.attackT -= dt;
  p.hp = Math.min(p.maxHp, p.hp + dt * 1.2);
}

/* ---------------- props ---------------- */
function updateProps(dt) {
  for (const c of crates) {
    c.vel.y -= 28 * dt;
    c.mesh.position.addScaledVector(c.vel, dt);
    c.mesh.rotation.x += c.av.x * dt;
    c.mesh.rotation.y += c.av.y * dt;
    c.mesh.rotation.z += c.av.z * dt;
    if (c.mesh.position.y < .8) {
      c.mesh.position.y = .8;
      if (c.vel.y < -4) c.vel.y = -c.vel.y * .35; else c.vel.y = 0;
      c.vel.x *= .9; c.vel.z *= .9;
      c.av.multiplyScalar(.9);
    }
    c.mesh.position.x = Math.max(-ARENA, Math.min(ARENA, c.mesh.position.x));
    c.mesh.position.z = Math.max(-ARENA, Math.min(ARENA, c.mesh.position.z));
  }
  for (let i = debris.length - 1; i >= 0; i--) {
    const d = debris[i];
    d.t -= dt;
    d.vel.y -= 26 * dt;
    d.mesh.position.addScaledVector(d.vel, dt);
    d.mesh.rotation.x += d.av.x * dt;
    d.mesh.rotation.y += d.av.y * dt;
    if (d.mesh.position.y < .4) { d.mesh.position.y = .4; d.vel.multiplyScalar(.5); }
    d.mesh.material.opacity = Math.min(1, d.t);
    if (d.t <= 0) {
      scene.remove(d.mesh);
      d.mesh.material.dispose();
      debris.splice(i, 1);
    }
  }
}

