    m.rotation.x = -Math.PI / 2;
    m.rotation.z = spin == null ? Math.random() * TAU : spin;
    m.position.set(pos.x, (pos.y || 0) + .06 + Math.random() * .03, pos.z);
    m.renderOrder = 3;
    m.scale.set(r * 2, r * 2, 1);
