      var m = new THREE.Mesh(PLANE, new THREE.MeshBasicMaterial({
        map: T.bolt, color: color, transparent: true, opacity: .85,
        depthWrite: false, side: THREE.DoubleSide, toneMapped: false
      }));
      m.rotation.x = -Math.PI / 2;
      m.rotation.z = -a;
