        r.elbowR.rotation.x = -1.5 * s + 1.25 * open;
        r.neck.rotation.x = .15 * s - .55 * open;
        r.spine.rotation.x = .12 * s - .28 * open;
        r.hips.position.y = r.hipsBaseY - .22 * s + .3 * open;
