        var coil = t < .28 ? E.out(t / .28) : Math.max(0, 1 - (t - .28) / .12);
        var out = t < .28 ? 0 : Math.min(1, (t - .28) / .12);
        if (t > .62) out = 1 + Math.min(1, (t - .62) / .1) * .1;      // the shove
        if (t > .82) out = 1.1 - E.out((t - .82) / .23) * .75;        // and back
        punchShape(r, coil, out, 1);
