  Object.assign(JJCHARCAST.megumi,{awakeCast:[castTotality,()=> (merged('ga1')?castDivineChimera:castChimera)(),()=> (merged('ga2')?castMaw:castToad)(),castGarden],scope:[GD],awakeIdle:tickGarden,awakeEnd:shutGarden});
