      FX.mangaLines(.5, .42);
      if (e && !e.dead) { e.anchorT = 1.8; e.anchorPos.copy(e.pos); e.stunT = Math.max(e.stunT || 0, 2.2); }

      var t = 0, tick = 0, n = 0;
