      variance: 0.22,
      revenge: 0.18,
      redirect: 0.35,
      dodge: 0.2,
      guard: 0.28,
      retreat: 0.35,
      combo: 0.25,
      team: 0.25,
      turn: 6,
      speed: 11.5
